// ===== TOEIC 聽力 Part 2（應答問題）第 7~31 題，共 12 份試卷 =====
// 來源：toeic_part2.json（逐題音檔，8 份）、toeic_part2_all.json（整份音檔，4 份）。
// kind: "files"＝每題一個音檔（Part2/<試卷>/<題號>.mp3，每個檔尾已含約 5 秒作答間隔），directions 是說明音檔；
//       "whole"＝整份一個音檔（含 Directions 與第 7~31 題）。starts／ends 是每題在整份音檔裡的開始與結束秒數，
//       用 ffmpeg 偵測每題後面約 5 秒的靜音算出（4 份音檔都剛好偵測到 25 段），用來顯示「目前播到第幾題」與單題重播。
// 題目欄位：no 題號；q 問句或陳述句；o 三個選項；a 正確答案字母；zh 問句中譯；ozh 三個選項中譯；audio 單題音檔路徑。
// 找不到音檔時，程式會改用系統語音朗讀。

PART2_EXAMS.push({"id": "A1", "label": "試卷 A1（逐題音檔）", "kind": "files", "dir": "Part2/A1", "directions": "Part2/A1/Part2 directions.mp3", "questions": [{"no": 7, "q": "Who will print the financial statements?", "o": ["(A) Anthony will.", "(B) Five pages long.", "(C) A quarterly budget report."], "a": "A", "zh": "誰會列印財務報表？", "ozh": ["恩索尼會。", "五頁長。", "季度預算報告。"], "audio": "Part2/A1/7.mp3"}, {"no": 8, "q": "Did you notice the new carpet in the hallway?", "o": ["(A) Whose car is that?", "(B) Actually, I didn't.", "(C) A flooring store nearby."], "a": "B", "zh": "你有注意到走廊上的新地毯嗎？", "ozh": ["那是誰的車？", "實際上，我沒有注意到。", "附近的鋪地材料店家。"], "audio": "Part2/A1/8.mp3"}, {"no": 9, "q": "Where did you leave your bicycle?", "o": ["(A) For a few hours.", "(B) Yes, it's brand-new.", "(C) Next to the bridge."], "a": "C", "zh": "你把腳踏車停在哪裡？", "ozh": ["幾個小時。", "是的，它是全新的。", "在橋旁邊。"], "audio": "Part2/A1/9.mp3"}, {"no": 10, "q": "When will the caterers be here?", "o": ["(A) Desserts and drinks.", "(B) The guest list.", "(C) At twelve o'clock."], "a": "C", "zh": "外辦外燴人員什麼時候會到？", "ozh": ["甜點與飲料。", "賓客名單。", "十二點時。"], "audio": "Part2/A1/10.mp3"}, {"no": 11, "q": "The weather forecast for next week calls for rain.", "o": ["(A) That's typical for this season.", "(B) I called, but he didn't answer.", "(C) Right after the evening news."], "a": "A", "zh": "下週的天氣預報顯示會下雨。", "ozh": ["這個季節通常如此。", "我打電話了但沒人接。", "晚間新聞剛結束後。"], "audio": "Part2/A1/11.mp3"}, {"no": 12, "q": "How quickly can we send these products to Berlin?", "o": ["(A) I'd like a one-way ticket, please.", "(B) We can get them there tomorrow.", "(C) Several new models a year."], "a": "B", "zh": "我們多快能把這些產品送到柏林？", "ozh": ["請給我一張單程票。", "明天就能送達。", "每年幾種新型號。"], "audio": "Part2/A1/12.mp3"}, {"no": 13, "q": "You received your payment, didn't you?", "o": ["(A) No, I didn't buy any.", "(B) The shipment's coming.", "(C) I'll look at my bank account."], "a": "C", "zh": "你收到款項了，對吧？", "ozh": ["不，我沒買。", "貨物要來了。", "我去確認一下我的銀行帳戶。"], "audio": "Part2/A1/13.mp3"}, {"no": 14, "q": "Why was the office move postponed?", "o": ["(A) I'll have it finished by then.", "(B) I hadn't heard about that.", "(C) Try the Smithtown post office."], "a": "B", "zh": "為什麼辦公室搬遷延期了？", "ozh": ["我到時會完成。", "我沒聽說這件事。", "試試史密斯鎮郵局。"], "audio": "Part2/A1/14.mp3"}, {"no": 15, "q": "Should we eat at home or go out?", "o": ["(A) They really liked it.", "(B) The recipe on page three.", "(C) What's less expensive?"], "a": "C", "zh": "我們要在家吃還是出去吃？", "ozh": ["他們真的很喜歡。", "第三頁的食譜。", "哪種比較划算？"], "audio": "Part2/A1/15.mp3"}, {"no": 16, "q": "Do you have time to review some applications now?", "o": ["(A) It has a great view.", "(B) He bought it yesterday.", "(C) I'm leaving in fifteen minutes."], "a": "C", "zh": "你現在有時間審查一些申請表嗎？", "ozh": ["景色很棒。", "他昨天買的。", "我十五分鐘後要離開。"], "audio": "Part2/A1/16.mp3"}, {"no": 17, "q": "Does your manufacturing plant produce textiles?", "o": ["(A) Oh, I didn't know that.", "(B) Yes, that's our main industry.", "(C) Over in the gardening section."], "a": "B", "zh": "你們的製造工廠生產紡織品嗎？", "ozh": ["噢，我不知道那件事。", "是的，那是我們的主營產業。", "在園藝區那邊。"], "audio": "Part2/A1/17.mp3"}, {"no": 18, "q": "When does the bus leave?", "o": ["(A) Eighteen dollars.", "(B) I believe you.", "(C) In thirty minutes."], "a": "C", "zh": "公車什麼時候發車？", "ozh": ["十八美元。", "我相信你。", "三十分鐘後。"], "audio": "Part2/A1/18.mp3"}, {"no": 19, "q": "Aren't we putting these books on sale next week?", "o": ["(A) Yes, they'll be 40 percent off.", "(B) No, I booked a trip for this week.", "(C) That's one of my favorite books."], "a": "A", "zh": "我們下週不是要特價銷售這些書嗎？", "ozh": ["對，到時打六折。", "不，我這週預訂了旅行。", "那是我最喜歡的書之一。"], "audio": "Part2/A1/19.mp3"}, {"no": 20, "q": "When will the designs for the new airport be revealed?", "o": ["(A) Turn right at the sign.", "(B) There were no flight cancellations.", "(C) Sometime next spring."], "a": "C", "zh": "新機場的設計圖什麼時候會公開？", "ozh": ["在指示牌處右轉。", "航班沒有取消。", "大約在明年春天。"], "audio": "Part2/A1/20.mp3"}, {"no": 21, "q": "This theater can seat about a hundred people, can't it?", "o": ["(A) Yes, at least that many.", "(B) The performance schedule is online.", "(C) A seat by the aisle, please."], "a": "A", "zh": "這間劇院大約能容納一百人，不是嗎？", "ozh": ["對，至少有那麼多。", "演出時間表在網路上。", "請給我靠走道的座位。"], "audio": "Part2/A1/21.mp3"}, {"no": 22, "q": "How long will the factory tour take?", "o": ["(A) The factors influencing his decision.", "(B) The new guide.", "(C) Probably a couple of hours."], "a": "C", "zh": "工廠參觀要花多久時間？", "ozh": ["影響他決定的因素。", "新導遊。", "大概兩小時左右。"], "audio": "Part2/A1/22.mp3"}, {"no": 23, "q": "What color should we paint the office?", "o": ["(A) Let me see the choices again.", "(B) An updated invoice.", "(C) You can print it in black and white."], "a": "A", "zh": "辦公室我們要刷什麼顏色？", "ozh": ["讓我再看一次顏色選項。", "更新後的發票。", "你可以用黑白列印。"], "audio": "Part2/A1/23.mp3"}, {"no": 24, "q": "Haven't we hired enough people?", "o": ["(A) No, we need someone for the night shift.", "(B) Order enough supplies for everyone.", "(C) Some résumés on file."], "a": "A", "zh": "我們僱用的人手還不夠嗎？", "ozh": ["還不夠，夜班還需要人。", "為每個人訂購足夠的用品。", "檔案庫裡的一些履歷。"], "audio": "Part2/A1/24.mp3"}, {"no": 25, "q": "Should we go to the networking seminar or the writing workshop?", "o": ["(A) I attended both last year.", "(B) Yes, the new shop on the corner.", "(C) That's the only one you have?"], "a": "A", "zh": "我們該去社交研討會還是寫作工作坊？", "ozh": ["我去年兩個都參加過。", "對，轉角那間新店家。", "你只有那一個嗎？"], "audio": "Part2/A1/25.mp3"}, {"no": 26, "q": "Where is our manager's new office?", "o": ["(A) No, just the main entrance.", "(B) It hasn't been assigned yet.", "(C) We didn't expect you to."], "a": "B", "zh": "我們經理的新辦公室在哪裡？", "ozh": ["不，只有主入口。", "還沒分配好。", "我們沒想到你會這樣做。"], "audio": "Part2/A1/26.mp3"}, {"no": 27, "q": "We should offer more international food options.", "o": ["(A) That sounds expensive.", "(B) No thanks, I just ate.", "(C) A flight to Brazil."], "a": "A", "zh": "我們應該提供更多國際餐點選擇。", "ozh": ["聽起來成本很高。", "不用了謝謝，我剛吃過。", "飛往巴西的航班。"], "audio": "Part2/A1/27.mp3"}, {"no": 28, "q": "Isn't it a little dark in here?", "o": ["(A) You can set it over there.", "(B) I ordered a bigger one.", "(C) We're going to show a video."], "a": "C", "zh": "這裡是不是有點暗？", "ozh": ["你可以放那邊。", "我訂了更大號的。", "因為我們等一下要播放影片。"], "audio": "Part2/A1/28.mp3"}, {"no": 29, "q": "Can you join us for a client meeting at four P.M.?", "o": ["(A) A new design project.", "(B) I made four copies in total.", "(C) I'm free all day."], "a": "C", "zh": "下午四點你能參加我們與客戶的會議嗎？", "ozh": ["一項新設計專案。", "我總共印了四份。", "我一整天都有空。"], "audio": "Part2/A1/29.mp3"}, {"no": 30, "q": "I don't think we'll make our sales quota this month.", "o": ["(A) I'll speak with the supervisor.", "(B) A one-week sale.", "(C) An article in tomorrow's paper."], "a": "A", "zh": "我覺得我們這個月達不到銷售配額。", "ozh": ["我會去和主管談談。", "為期一週的特賣會。", "明天報紙上的文章。"], "audio": "Part2/A1/30.mp3"}, {"no": 31, "q": "Would you like to use our computer while you wait for Mr. Fuller?", "o": ["(A) Please check the weight on that package.", "(B) That would be great.", "(C) Yes, it is."], "a": "B", "zh": "在等待富勒先生時，您要使用我們的電腦嗎？", "ozh": ["請確認那個包裹的重量。", "太棒了，謝謝。", "對，是的。"], "audio": "Part2/A1/31.mp3"}]});
PART2_EXAMS.push({"id": "A3", "label": "試卷 A3（逐題音檔）", "kind": "files", "dir": "Part2/A3", "directions": "Part2/A3/Part2 directions.mp3", "questions": [{"no": 7, "q": "How long was your vacation?", "o": ["(A) Yes, Ms. Ito's going to be there.", "(B) Next summer in August.", "(C) A week and a half."], "a": "C", "zh": "你的假期有多長？", "ozh": ["是的，伊東女士會去。", "明年八月。", "一個半星期。"], "audio": "Part2/A3/7.mp3"}, {"no": 8, "q": "Yoshi, did you buy your plane ticket yet?", "o": ["(A) Is it still raining?", "(B) Yes, I bought it yesterday.", "(C) It's my favorite brand."], "a": "B", "zh": "Yoshi，你買機票了嗎？", "ozh": ["還在下雨嗎？", "對，我昨天買了。", "那是我最喜歡的品牌。"], "audio": "Part2/A3/8.mp3"}, {"no": 9, "q": "Could you hold the door open, please?", "o": ["(A) Through the front door.", "(B) Sorry, there aren't any left.", "(C) Sure, no problem."], "a": "C", "zh": "可以請你幫忙開著門嗎？", "ozh": ["穿過前門。", "抱歉，一個都不剩了。", "沒問題。"], "audio": "Part2/A3/9.mp3"}, {"no": 10, "q": "What do you want to eat for lunch?", "o": ["(A) By the escalator.", "(B) It was delicious.", "(C) Let's have sandwiches."], "a": "C", "zh": "你午餐想吃什麼？", "ozh": ["手扶梯旁邊。", "很好吃。", "我們吃三明治吧。"], "audio": "Part2/A3/10.mp3"}, {"no": 11, "q": "Why has the company's annual profit decreased?", "o": ["(A) Because sales have fallen.", "(B) A detailed graph.", "(C) The company calendar is finished."], "a": "A", "zh": "為什麼公司的年利潤減少了？", "ozh": ["因為銷售額下滑了。", "詳細的圖表。", "公司日曆印好了。"], "audio": "Part2/A3/11.mp3"}, {"no": 12, "q": "Where's the client directory you borrowed?", "o": ["(A) A wonderful film director.", "(B) I put it back in the drawer.", "(C) No, she didn't need it."], "a": "B", "zh": "你借走的客戶通訊錄在哪裡？", "ozh": ["一位優秀的電影導演。", "我放回抽屜裡了。", "不，她不需要。"], "audio": "Part2/A3/12.mp3"}, {"no": 13, "q": "This is your bag, isn't it?", "o": ["(A) No, they usually don't.", "(B) We'll meet in the baggage claim area.", "(C) Yes, I must have forgotten it."], "a": "C", "zh": "這是你的包包，對吧？", "ozh": ["不，他們通常不會。", "我們在行李提領區碰頭。", "對，我一定是不小心忘了。"], "audio": "Part2/A3/13.mp3"}, {"no": 14, "q": "Why don't we check the weather before we leave?", "o": ["(A) OK, I'll do that.", "(B) About seven days.", "(C) No, a checking account."], "a": "A", "zh": "我們出發前為什麼不先查一下天氣？", "ozh": ["好，我去查。", "大約七天。", "不，是支票帳戶。"], "audio": "Part2/A3/14.mp3"}, {"no": 15, "q": "Who's on the team for this marketing campaign?", "o": ["(A) So-Hee just updated the list of names.", "(B) During an earlier shift.", "(C) No, it was last week."], "a": "A", "zh": "誰在這個行銷活動團隊名單中？", "ozh": ["So-Hee 剛更新了名單。", "在之前的輪班時間。", "不，是上週。"], "audio": "Part2/A3/15.mp3"}, {"no": 16, "q": "Can I put these boxes in the storage room?", "o": ["(A) The yearly inspection.", "(B) My phone stores over 500 photos.", "(C) There's some space in this closet."], "a": "C", "zh": "我可以把這些箱子放進儲藏室嗎？", "ozh": ["年度檢查。", "我的手機存了500多張照片。", "這個壁櫥裡還有些空間。"], "audio": "Part2/A3/16.mp3"}, {"no": 17, "q": "Where did Naomi save the files for our presentation?", "o": ["(A) Maybe today or tomorrow.", "(B) How can you tell?", "(C) She sent us an e-mail about that."], "a": "C", "zh": "Naomi 把我們簡報的檔案存去哪裡了？", "ozh": ["也許今天或明天。", "你怎麼看得出來？", "她有寄電子郵件告訴我們。"], "audio": "Part2/A3/17.mp3"}, {"no": 18, "q": "How did you hear about the open position at our pharmacy?", "o": ["(A) For some prescription medication.", "(B) I heard that, too.", "(C) A friend told me about it."], "a": "C", "zh": "你是如何得知我們藥局有職缺的？", "ozh": ["為了處方藥物。", "我也有聽說。", "朋友告訴我的。"], "audio": "Part2/A3/18.mp3"}, {"no": 19, "q": "I think our new packaging should use less plastic.", "o": ["(A) I'm waiting for a package.", "(B) That's a great idea.", "(C) Some plastic spoons."], "a": "B", "zh": "我覺得我們的新包裝應該少用塑膠。", "ozh": ["我在等包裹。", "那是個好主意。", "一些塑膠湯匙。"], "audio": "Part2/A3/19.mp3"}, {"no": 20, "q": "Should we start production before or after the holidays?", "o": ["(A) Yes, that's fine.", "(B) A factory tour.", "(C) Talk to the manager."], "a": "C", "zh": "我們應該在假期前還是假期後開始生產？", "ozh": ["好，沒問題。", "工廠參觀。", "去跟經理討論看看。"], "audio": "Part2/A3/20.mp3"}, {"no": 21, "q": "Which of the paintings in the gallery have already been sold?", "o": ["(A) With the museum guide.", "(B) Only the one near the entrance.", "(C) It took a month to paint."], "a": "B", "zh": "畫廊裡的哪些畫作已經賣出了？", "ozh": ["與博物館導覽員。", "只有靠近入口的那幅。", "花了一個月才畫好。"], "audio": "Part2/A3/21.mp3"}, {"no": 22, "q": "Didn't you want to view the new office space this afternoon?", "o": ["(A) With views of the river.", "(B) Yes, but I have another appointment.", "(C) Two large conference rooms."], "a": "B", "zh": "你今天下午不是想去看新的辦公空間嗎？", "ozh": ["擁有河景。", "對，但我有另一個約。", "兩個大會議室。"], "audio": "Part2/A3/22.mp3"}, {"no": 23, "q": "Where's the publishing convention going to be?", "o": ["(A) For three days.", "(B) It changes every year.", "(C) Two months from now."], "a": "B", "zh": "出版研討會要在哪裡舉辦？", "ozh": ["為期三天。", "每年地點都不一樣。", "從現在起兩個月。"], "audio": "Part2/A3/23.mp3"}, {"no": 24, "q": "Who placed the monthly supply order?", "o": ["(A) That information's on the invoice.", "(B) We'd like a thousand.", "(C) I'll schedule a service call."], "a": "A", "zh": "是誰下單這個月的用品採購？", "ozh": ["那項資訊在發票上。", "我們想要一千個。", "我會安排維修服務。"], "audio": "Part2/A3/24.mp3"}, {"no": 25, "q": "When will the next financial report be coming out?", "o": ["(A) Yes, they did.", "(B) In the financial district.", "(C) Kevin would know that."], "a": "C", "zh": "下一份財務報告什麼時候出來？", "ozh": ["對，他們做了。", "在金融區。", "Kevin 會知道。"], "audio": "Part2/A3/25.mp3"}, {"no": 26, "q": "Sales of our portable printers keep increasing.", "o": ["(A) They are popular with business travelers.", "(B) You can find them on the third floor.", "(C) I have a document to photocopy."], "a": "A", "zh": "我們可攜式印表機的銷售額持續成長。", "ozh": ["它們深受商務旅客歡迎。", "你能在三樓找到。", "我有一份文件要影印。"], "audio": "Part2/A3/26.mp3"}, {"no": 27, "q": "You still have your receipt for this purchase, don't you?", "o": ["(A) It's my favorite dessert recipe!", "(B) I haven't seen him today.", "(C) Absolutely, it's right here."], "a": "C", "zh": "你買這項商品收據還留著吧？", "ozh": ["那是我最喜歡的甜點食譜！", "我今天還沒看到他。", "當然，就在這裡。"], "audio": "Part2/A3/27.mp3"}, {"no": 28, "q": "When will the archaeological team return from their fieldwork?", "o": ["(A) A team of ten researchers.", "(B) They'll transfer in Tokyo.", "(C) Around five o'clock."], "a": "C", "zh": "考古隊什麼時候會田野調查結束歸來？", "ozh": ["十名研究人員的團隊。", "他們會在東京轉機。", "大約五點鐘。"], "audio": "Part2/A3/28.mp3"}, {"no": 29, "q": "I have another item to add to the meeting agenda.", "o": ["(A) It was really relaxing.", "(B) It's a 30 percent discount.", "(C) Ben's organizing this meeting."], "a": "C", "zh": "我還有一個項目要加入會議議程中。", "ozh": ["真的很令人放鬆。", "這是七折優惠。", "Ben 正在負責安排這次會議。"], "audio": "Part2/A3/29.mp3"}, {"no": 30, "q": "Would you like to try the chicken or the beef curry?", "o": ["(A) I'll pay with a credit card.", "(B) It's too heavy to carry.", "(C) Is there a vegetarian option?"], "a": "C", "zh": "你想嘗試雞肉咖哩還是牛肉咖哩？", "ozh": ["我會用信用卡付款。", "太重了拿不動。", "有素食的選項嗎？"], "audio": "Part2/A3/30.mp3"}, {"no": 31, "q": "Didn't Mr. Henderson cancel his physical exam today?", "o": ["(A) I can't access the online schedule right now.", "(B) Usually for an hour.", "(C) What's the number for the pharmacy?"], "a": "A", "zh": "Henderson 先生今天不是取消體檢了嗎？", "ozh": ["我現在無法進入線上行程表查看。", "通常一小時。", "藥局的電話是多少？"], "audio": "Part2/A3/31.mp3"}]});
PART2_EXAMS.push({"id": "B1", "label": "試卷 B1（逐題音檔）", "kind": "files", "dir": "Part2/B1", "directions": "Part2/B1/Part2 directions.mp3", "questions": [{"no": 7, "q": "What time does the restaurant close?", "o": ["(A) At eleven o'clock.", "(B) It's close to the library.", "(C) No, it doesn't."], "a": "A", "zh": "這家餐廳幾點關門？", "ozh": ["十一點。", "靠近圖書館。", "不，它沒有。"], "audio": "Part2/B1/7.mp3"}, {"no": 8, "q": "Who should I see about updating the Langdon account?", "o": ["(A) It's due by next Monday.", "(B) Mr. Travis is in charge of that.", "(C) For my laptop."], "a": "B", "zh": "關於更新朗頓帳戶，我該找誰？", "ozh": ["下週一前到期。", "Travis 先生負責該業務。", "為了我的筆電。"], "audio": "Part2/B1/8.mp3"}, {"no": 9, "q": "How long will it take to fix the copy machine?", "o": ["(A) About an hour.", "(B) Once every two weeks.", "(C) Sure, I can fix it."], "a": "A", "zh": "修好影印機需要多久？", "ozh": ["大約一小時。", "每兩週一次。", "當然，我可以修。"], "audio": "Part2/B1/9.mp3"}, {"no": 10, "q": "Did you enjoy the dance performance last night?", "o": ["(A) A ballet company from Argentina.", "(B) Yes, it was even better than I expected.", "(C) A few more nights."], "a": "B", "zh": "你喜歡昨晚的舞蹈演出嗎？", "ozh": ["來自阿根廷的芭蕾舞團。", "喜歡，比我預期的還棒。", "再過幾個晚上。"], "audio": "Part2/B1/10.mp3"}, {"no": 11, "q": "You've sent the invitations, haven't you?", "o": ["(A) Yes, I'll have some.", "(B) Which bakery?", "(C) No, Peter did."], "a": "C", "zh": "你已經寄出邀請函了，不是嗎？", "ozh": ["對，我要一些。", "哪家麵包店？", "沒有，是 Peter 寄的。"], "audio": "Part2/B1/11.mp3"}, {"no": 12, "q": "Can we try that Brazilian café tonight?", "o": ["(A) There were a few more than that.", "(B) I went there last week.", "(C) A reservation for five."], "a": "B", "zh": "我們今晚可以去試試那家巴西咖啡館嗎？", "ozh": ["比那個還多一些。", "我上週去過了。", "五人的預約。"], "audio": "Part2/B1/12.mp3"}, {"no": 13, "q": "When will my paperwork be ready?", "o": ["(A) On November second.", "(B) A variety of paper products.", "(C) Yes, a ten percent increase."], "a": "A", "zh": "我的文件什麼時候會準備好？", "ozh": ["十一月二日。", "各式紙製品。", "是的，增加百分之十。"], "audio": "Part2/B1/13.mp3"}, {"no": 14, "q": "Where's the entrance to the hotel?", "o": ["(A) We've already booked the room.", "(B) Do you offer a discount?", "(C) Around the corner to the right."], "a": "C", "zh": "飯店的入口在哪裡？", "ozh": ["我們已經訂房了。", "你們有提供折扣嗎？", "轉角右轉。"], "audio": "Part2/B1/14.mp3"}, {"no": 15, "q": "How do you like your new apartment?", "o": ["(A) I made an appointment yesterday.", "(B) The third floor.", "(C) The location is perfect."], "a": "C", "zh": "你覺得你的新公寓怎麼樣？", "ozh": ["我昨天預約了。", "三樓。", "地理位置非常好。"], "audio": "Part2/B1/15.mp3"}, {"no": 16, "q": "Whose glasses are these?", "o": ["(A) A history class.", "(B) They're not mine.", "(C) A stronger prescription."], "a": "B", "zh": "這是誰的眼鏡？", "ozh": ["歷史課。", "不是我的。", "更度數深的處方。"], "audio": "Part2/B1/16.mp3"}, {"no": 17, "q": "Could you take these packages to the post office?", "o": ["(A) I'll be free after my conference call.", "(B) They're packaged by the dozen.", "(C) I haven't received any mail."], "a": "A", "zh": "你能把這些包裹拿去郵局嗎？", "ozh": ["我電話會議開完後就有空。", "它們是以打為單位包裝的。", "我沒收到任何郵件。"], "audio": "Part2/B1/17.mp3"}, {"no": 18, "q": "Why is the street closed?", "o": ["(A) Go straight ahead.", "(B) It's nearby.", "(C) Because they're doing repair work."], "a": "C", "zh": "為什麼這條街封閉了？", "ozh": ["直直走。", "在附近。", "因為正在進行施工維修。"], "audio": "Part2/B1/18.mp3"}, {"no": 19, "q": "Is the doctor in today?", "o": ["(A) How often?", "(B) That's not a good day.", "(C) No, she's not."], "a": "C", "zh": "醫生今天有看診嗎？", "ozh": ["多久一次？", "那不是個好日子。", "沒有，她今天不在。"], "audio": "Part2/B1/19.mp3"}, {"no": 20, "q": "What's going on in the building next door?", "o": ["(A) A reception's being held.", "(B) But I just turned it off.", "(C) I'm sure you're next."], "a": "A", "zh": "隔壁大樓發生什麼事了？", "ozh": ["正在舉辦招待會。", "但我剛剛才關掉。", "我確定下一個輪到你。"], "audio": "Part2/B1/20.mp3"}, {"no": 21, "q": "That theater always sells out quickly, doesn't it?", "o": ["(A) I prefer comedies.", "(B) We sat in the first row.", "(C) True, so let's get our tickets now."], "a": "C", "zh": "那家劇院總是很快售罄門票，對吧？", "ozh": ["我比較喜歡喜劇。", "我們坐在第一排。", "沒錯，所以我們現在快買票吧。"], "audio": "Part2/B1/21.mp3"}, {"no": 22, "q": "Do you want to fly to Sydney or go by train?", "o": ["(A) You know I don't like flying.", "(B) It was a pretty short trip.", "(C) To attend my sister's graduation."], "a": "A", "zh": "你想搭飛機去雪梨還是坐火車？", "ozh": ["你知道我不喜歡搭飛機。", "這是一趟相當短的旅程。", "去參加我妹妹的畢業典禮。"], "audio": "Part2/B1/22.mp3"}, {"no": 23, "q": "Where'd you find that lovely winter coat?", "o": ["(A) Thank you, it was a gift.", "(B) Every January.", "(C) No, I haven't found them."], "a": "A", "zh": "你在哪裡買到那件好看的冬用大衣？", "ozh": ["謝謝你，那是禮物。", "每年一月。", "不，我還沒找到它們。"], "audio": "Part2/B1/23.mp3"}, {"no": 24, "q": "Should we remind Ms. Woods to send us the budget report?", "o": ["(A) I'd like to meet the reporter here.", "(B) Sales projections for the first quarter.", "(C) But the deadline isn't for another week."], "a": "C", "zh": "我們需要提醒伍茲女士寄預算報告給我們嗎？", "ozh": ["我想在這裡見記者。", "第一季銷售預測。", "但距離截止日期還有一週。"], "audio": "Part2/B1/24.mp3"}, {"no": 25, "q": "When does Mr. Cho want to pick up his cake?", "o": ["(A) I'll carry it to the car for you.", "(B) He said he'd be in around three o'clock.", "(C) For his colleagues."], "a": "B", "zh": "趙先生想什麼時候拿他的蛋糕？", "ozh": ["我幫你拿去車上。", "他說他大約三點會過來。", "為了他的同事。"], "audio": "Part2/B1/25.mp3"}, {"no": 26, "q": "I haven't heard who the board chose as a chairperson.", "o": ["(A) Tomorrow morning at the latest.", "(B) Please take a seat.", "(C) I believe it was Mr. Peterson."], "a": "C", "zh": "我還沒聽說董事會選了誰當主席。", "ozh": ["最晚明天早上。", "請坐。", "我相信是彼得森先生。"], "audio": "Part2/B1/26.mp3"}, {"no": 27, "q": "Will we focus on advertising in print media or online?", "o": ["(A) They're waiting in line.", "(B) Yes, it looks great.", "(C) Let's see what the team thinks."], "a": "C", "zh": "我們廣告重點要放在平面媒體還是線上？", "ozh": ["他們在排隊。", "是的，看起來很棒。", "看團隊意見如何。"], "audio": "Part2/B1/27.mp3"}, {"no": 28, "q": "Do you want to go to the art gallery opening on Friday evening?", "o": ["(A) Sorry, I'll be out of town.", "(B) I thought it was outstanding, too.", "(C) Her most recent work."], "a": "A", "zh": "你週五晚上想去藝廊開幕式嗎？", "ozh": ["抱歉，我那時會出外地。", "我也覺得非常傑出。", "她最近的作品。"], "audio": "Part2/B1/28.mp3"}, {"no": 29, "q": "We'll have to cancel the company picnic.", "o": ["(A) Two days before the event?", "(B) Which catering service?", "(C) Yes, they had one."], "a": "A", "zh": "我們必須取消公司野餐。", "ozh": ["在活動前兩天取消？", "哪家外燴服務？", "是的，他們有一個。"], "audio": "Part2/B1/29.mp3"}, {"no": 30, "q": "Don't you know how to use the new computer system?", "o": ["(A) I was hoping you could train me.", "(B) No, she doesn't use it.", "(C) At the Fourth Street branch."], "a": "A", "zh": "你不知道怎麼使用新的電腦系統嗎？", "ozh": ["我原本希望你能教我。", "不，她沒在用。", "在第四街分行。"], "audio": "Part2/B1/30.mp3"}, {"no": 31, "q": "Why hasn't Jason been in the office all week?", "o": ["(A) No, I haven't seen him.", "(B) Typically until six o'clock or so.", "(C) You'll have to ask his manager."], "a": "C", "zh": "Jason 怎麼一整週都沒來辦公室？", "ozh": ["沒有，我沒看到他。", "通常到六點左右。", "你必須問他的經理。"], "audio": "Part2/B1/31.mp3"}]});
PART2_EXAMS.push({"id": "B3", "label": "試卷 B3（逐題音檔）", "kind": "files", "dir": "Part2/B3", "directions": "Part2/B3/Part2 directions.mp3", "questions": [{"no": 7, "q": "Where can I find the printer?", "o": ["(A) Thirty pages at a time.", "(B) Monday to Friday.", "(C) Down the hall to your left."], "a": "C", "zh": "印表機在哪裡？", "ozh": ["一次三十頁。", "週一到週五。", "走廊底左手邊。"], "audio": "Part2/B3/7.mp3"}, {"no": 8, "q": "Who will be going to the exposition this year?", "o": ["(A) It was a good experience.", "(B) Several of our colleagues.", "(C) The beginning of October."], "a": "B", "zh": "今年誰會去博覽會？", "ozh": ["那是一次很好的體驗。", "我們的幾位同事。", "十月初。"], "audio": "Part2/B3/8.mp3"}, {"no": 9, "q": "Would you like me to bring you another soft drink?", "o": ["(A) That's OK, I don't want one.", "(B) No, that's the first time I've heard it.", "(C) The dinner reservation's at eight."], "a": "A", "zh": "需要我幫你拿另一杯軟性飲料嗎？", "ozh": ["不用了，我不需要。", "沒有，這是我第一次聽說。", "晚餐預約在八點。"], "audio": "Part2/B3/9.mp3"}, {"no": 10, "q": "Is Maria going to present the sales report, or are you doing it?", "o": ["(A) We're doing it together.", "(B) It's on sale today.", "(C) In a couple of weeks."], "a": "A", "zh": "瑪麗亞要報告銷售報告，還是由你報告？", "ozh": ["我們要一起報告。", "今天有特價。", "幾週內。"], "audio": "Part2/B3/10.mp3"}, {"no": 11, "q": "What's the name of the new intern in the design department?", "o": ["(A) I think it's Sammy, but I'm not sure.", "(B) We sent in the blueprint.", "(C) Yes, I enjoyed the internship."], "a": "A", "zh": "設計部新實習生叫什麼名字？", "ozh": ["我想是薩米，但我不確定。", "我們寄出了藍圖。", "對，我很享受實習。"], "audio": "Part2/B3/11.mp3"}, {"no": 12, "q": "Are you ready for your next patient?", "o": ["(A) Usually thirty minutes.", "(B) I already read it.", "(C) Sure, send her in."], "a": "C", "zh": "你準備好接見下一位病人了嗎？", "ozh": ["通常三十分鐘。", "我已經讀過了。", "當然，請她進來。"], "audio": "Part2/B3/12.mp3"}, {"no": 13, "q": "How do you turn the packaging machine on?", "o": ["(A) Next to the storage area.", "(B) Push the green button.", "(C) No, I haven't seen her."], "a": "B", "zh": "包裝機要怎麼開？", "ozh": ["儲藏區旁邊。", "按下綠色按鈕。", "不，我沒看到她。"], "audio": "Part2/B3/13.mp3"}, {"no": 14, "q": "You went to the soccer match last week, didn't you?", "o": ["(A) These socks don't match.", "(B) A local sports writer.", "(C) I did—my favorite team won!"], "a": "C", "zh": "你上週去了足球比賽，對吧？", "ozh": ["這雙襪子不搭配。", "當地體育記者。", "對啊—我最喜歡的球隊贏了！"], "audio": "Part2/B3/14.mp3"}, {"no": 15, "q": "Will you stay after the show to meet the musicians?", "o": ["(A) I think so too.", "(B) Almost as long as the previous show.", "(C) Don't they leave as soon as it's over?"], "a": "C", "zh": "演出結束後你會留下來見音樂家嗎？", "ozh": ["我也這麼認為。", "幾乎和上一場一樣長。", "他們不是結束後就馬上離開了嗎？"], "audio": "Part2/B3/15.mp3"}, {"no": 16, "q": "How often do you buy new glasses?", "o": ["(A) About three to five days per order.", "(B) The store on Robin Street.", "(C) I actually switched to contact lenses."], "a": "C", "zh": "你多久買一次新眼鏡？", "ozh": ["每次訂單約三到五天。", "羅賓街上的那家店。", "我其實改戴隱形眼鏡了。"], "audio": "Part2/B3/16.mp3"}, {"no": 17, "q": "Do you know who this jacket belongs to?", "o": ["(A) Yes, very expensive.", "(B) No, where did you find it?", "(C) It won't take too long."], "a": "B", "zh": "你知道這件夾克是誰的嗎？", "ozh": ["是的，非常貴。", "不知道，你在哪裡找到的？", "不會花太長時間。"], "audio": "Part2/B3/17.mp3"}, {"no": 18, "q": "Let's work through lunch to finish the project.", "o": ["(A) A sandwich and an apple.", "(B) But I really need a break!", "(C) It was this morning."], "a": "B", "zh": "我們午餐不休息繼續工作把專案做完吧。", "ozh": ["一個三明治和一顆蘋果。", "但我真的很需要休息！", "那是今天早上。"], "audio": "Part2/B3/18.mp3"}, {"no": 19, "q": "Why does Dr. Yang need another lab assistant?", "o": ["(A) I didn't know he requested one.", "(B) At least three years experience.", "(C) Yes, we visited the new lab."], "a": "A", "zh": "為什麼楊博士需要另一名實驗室助理？", "ozh": ["我不知道他有要求。", "至少三年經驗。", "對，我們參觀了新實驗室。"], "audio": "Part2/B3/19.mp3"}, {"no": 20, "q": "Dr. Martinez will be free this afternoon.", "o": ["(A) I've been here before.", "(B) What about tomorrow morning?", "(C) The pharmacy is just downstairs."], "a": "B", "zh": "馬丁尼茲醫生今天下午有空。", "ozh": ["我以前來過這裡。", "那明天早上呢？", "藥局就在樓下。"], "audio": "Part2/B3/20.mp3"}, {"no": 21, "q": "Can I write an article on the festival for Tuesday's newspaper?", "o": ["(A) You're right; it's too long.", "(B) The deadline has passed.", "(C) He's at the museum now."], "a": "B", "zh": "我可以寫一篇關於節慶的文章刊登在週二的報紙嗎？", "ozh": ["你說得對；太長了。", "截稿時間已經過了。", "他現在在博物館。"], "audio": "Part2/B3/21.mp3"}, {"no": 22, "q": "Don't you want to see the apartment?", "o": ["(A) West of Main Street.", "(B) We had to order a part.", "(C) I've found a place already."], "a": "C", "zh": "你不想看那間公寓嗎？", "ozh": ["主街以西。", "我們必須訂購零件。", "我已經找到住處了。"], "audio": "Part2/B3/22.mp3"}, {"no": 23, "q": "Should I order the supplies now, or wait until next week?", "o": ["(A) A total of seventy-five dollars.", "(B) Actually, I already sent the order.", "(C) It's in the supply closet."], "a": "B", "zh": "我現在該下單訂用品，還是等到下週？", "ozh": ["總共七十五美元。", "實際上，我已經把訂單寄出了。", "在用品櫃裡。"], "audio": "Part2/B3/23.mp3"}, {"no": 24, "q": "How should I store these photographs?", "o": ["(A) Mateo is responsible for that.", "(B) From the company picnic.", "(C) Yes, the staff is very helpful."], "a": "A", "zh": "我該如何保存這些照片？", "ozh": ["馬泰奧負責處理那個。", "來自公司野餐。", "對，員工很有幫助。"], "audio": "Part2/B3/24.mp3"}, {"no": 25, "q": "Where should I set up the equipment for the photo shoot?", "o": ["(A) That's scheduled for next week.", "(B) It was taken in Amsterdam.", "(C) I got it from the electronics store."], "a": "A", "zh": "我該在哪裡架設攝影裝備？", "ozh": ["那個排在下週進行。", "那是在阿姆斯特丹拍的。", "我從電子用品店買的。"], "audio": "Part2/B3/25.mp3"}, {"no": 26, "q": "You haven't seen Jennifer today, have you?", "o": ["(A) I saw her a while ago.", "(B) I don't have any yet.", "(C) No, my name's Janet."], "a": "A", "zh": "你今天還沒看到珍妮佛，對吧？", "ozh": ["我不久前有看到她。", "我還沒有。", "不，我叫珍妮特。"], "audio": "Part2/B3/26.mp3"}, {"no": 27, "q": "Could you help me find the Murphy Company file?", "o": ["(A) I'm fine, thanks.", "(B) He left a while ago.", "(C) I don't work on that account."], "a": "C", "zh": "你能幫我找默菲公司的檔案嗎？", "ozh": ["我很好，謝謝。", "他不久前離開了。", "我沒負責那個客戶。"], "audio": "Part2/B3/27.mp3"}, {"no": 28, "q": "Why has the workshop been canceled?", "o": ["(A) About twenty minutes ago.", "(B) In Room Fourteen.", "(C) Because many people couldn't attend."], "a": "C", "zh": "為什麼工作坊取消了？", "ozh": ["大約二十分鐘前。", "在十四號房。", "因為許多人無法出席。"], "audio": "Part2/B3/28.mp3"}, {"no": 29, "q": "You've already signed the contract, haven't you?", "o": ["(A) I'll do it right now.", "(B) Yes, I turned it off.", "(C) What does the sign say?"], "a": "A", "zh": "你已經簽合同了，不是嗎？", "ozh": ["我現在馬上簽。", "對，我關掉了。", "告示牌寫什麼？"], "audio": "Part2/B3/29.mp3"}, {"no": 30, "q": "I thought the professional development training was really helpful.", "o": ["(A) I'd be happy to help.", "(B) That was my experience, too.", "(C) Sure, I'll take care of it."], "a": "B", "zh": "我覺得職涯發展培訓非常有幫助。", "ozh": ["我很樂意幫忙。", "我也有同感。", "沒問題，我會處理。"], "audio": "Part2/B3/30.mp3"}, {"no": 31, "q": "Where did you make the dinner reservation?", "o": ["(A) Tomorrow at twelve-thirty.", "(B) Didn't you make it?", "(C) For fourteen people."], "a": "B", "zh": "你在哪裡訂晚餐位置的？", "ozh": ["明天十二點半。", "不是你訂的嗎？", "給十四個人。"], "audio": "Part2/B3/31.mp3"}]});
PART2_EXAMS.push({"id": "C1", "label": "試卷 C1（逐題音檔）", "kind": "files", "dir": "Part2/C1", "directions": "Part2/C1/Part2 directions.mp3", "questions": [{"no": 7, "q": "Did you see today's newspaper headlines?", "o": ["(A) Yes, I'm headed to the store now.", "(B) No. What did they say?", "(C) Yes, I saw him in the reference room."], "a": "B", "zh": "你有看到今天的報紙頭條嗎？", "ozh": ["有，我現在要去商店。", "沒有，頭條寫了什麼？", "有，我在參考室看到他。"], "audio": "Part2/C1/7.mp3"}, {"no": 8, "q": "When should we be able to see the results?", "o": ["(A) A week ago.", "(B) Yes, you can.", "(C) Within a month."], "a": "C", "zh": "我們什麼時候能看到結果？", "ozh": ["一個星期前。", "對，你可以。", "一個月之內。"], "audio": "Part2/C1/8.mp3"}, {"no": 9, "q": "How do you feel about their latest offer?", "o": ["(A) Do you agree with me?", "(B) No, I didn't feel it was too late.", "(C) I think it's perfectly acceptable."], "a": "C", "zh": "你覺得他們最新的報價怎麼樣？", "ozh": ["你同意我嗎？", "不，我不覺得太晚。", "我覺得完全可以接受。"], "audio": "Part2/C1/9.mp3"}, {"no": 10, "q": "How about joining us for lunch?", "o": ["(A) Thanks, but I have to work on this report.", "(B) Around 12:30.", "(C) There will be six of us all together."], "a": "A", "zh": "要不要和我們一起吃午餐？", "ozh": ["謝謝，但我必須做這份報告。", "大約十二點半。", "我們總共有六個人。"], "audio": "Part2/C1/10.mp3"}, {"no": 11, "q": "Can you tell me where I can buy stamps?", "o": ["(A) I was told that it's a good buy.", "(B) There's a post office down on Fifth Street.", "(C) Yes, you can buy them."], "a": "B", "zh": "能告訴我哪裡可以買郵票嗎？", "ozh": ["有人跟我說那是划算的買賣。", "第五街那邊有一家郵局。", "對，你可以買。"], "audio": "Part2/C1/11.mp3"}, {"no": 12, "q": "Why didn't you call my mobile phone?", "o": ["(A) Because they were all sold out.", "(B) To reach me in a hurry, call this number.", "(C) I didn't have the number with me."], "a": "C", "zh": "你為什麼沒打我的手機？", "ozh": ["因為全部賣光了。", "有急事找我請撥這個號碼。", "我身上沒帶你的號碼。"], "audio": "Part2/C1/12.mp3"}, {"no": 13, "q": "Would you like to go on a tour of the museum?", "o": ["(A) Yes, I enjoyed going at my own pace.", "(B) I'd rather look at the pieces on my own.", "(C) I've been to all the museums in Paris."], "a": "B", "zh": "你想參加博物館導覽嗎？", "ozh": ["是的，我喜歡照自己的步調。", "我比較想自己欣賞展品。", "去過巴黎所有的博物館。"], "audio": "Part2/C1/13.mp3"}, {"no": 14, "q": "Maggie is fitting in well, isn't she?", "o": ["(A) They didn't fit so I returned them.", "(B) Yes, everyone seems to like her.", "(C) No, she hasn't been here today."], "a": "B", "zh": "麥琪適應得很好，不是嗎？", "ozh": ["它們不合身所以我退掉了。", "對，大家好像都很喜歡她。", "不，她今天沒來。"], "audio": "Part2/C1/14.mp3"}, {"no": 15, "q": "How do you spell your last name?", "o": ["(A) There are several ways to pronounce it.", "(B) I don't know if we have room.", "(C) It's F-U-J-I-T-A."], "a": "C", "zh": "你的姓氏怎麼拼寫？", "ozh": ["有幾種發音方式。", "我不知道我們有沒有房間。", "是 F-U-J-I-T-A。"], "audio": "Part2/C1/15.mp3"}, {"no": 16, "q": "Aren't there any direct flights to London from here?", "o": ["(A) The director will arrive late.", "(B) No, not anymore.", "(C) For a business trip."], "a": "B", "zh": "從這裡沒有直飛倫敦的航班了嗎？", "ozh": ["主任會晚到。", "對，現在沒有了。", "去出差。"], "audio": "Part2/C1/16.mp3"}, {"no": 17, "q": "Can you drop this packet off at the accountant's for me?", "o": ["(A) You won't need a jacket.", "(B) Sure, I'm heading there now.", "(C) No, it's not broken."], "a": "B", "zh": "你能幫我把這個包裹拿給會計師嗎？", "ozh": ["你不需要外套。", "沒問題，我現在正要過去。", "不，沒有壞。"], "audio": "Part2/C1/17.mp3"}, {"no": 18, "q": "These new trains are so much faster.", "o": ["(A) I already completed my training.", "(B) Sorry, I don't have any.", "(C) They really are."], "a": "C", "zh": "這些新火車快多了。", "ozh": ["我已經完成培訓了。", "抱歉，我沒有。", "真的快很多。"], "audio": "Part2/C1/18.mp3"}, {"no": 19, "q": "I'd like a refill of this medication, please.", "o": ["(A) About a hundred pills.", "(B) When would you like to pick it up?", "(C) You're welcome."], "a": "B", "zh": "我想重新拿這個藥的續方。", "ozh": ["大約一百顆藥丸。", "您想什麼時候來拿？", "不客氣。"], "audio": "Part2/C1/19.mp3"}, {"no": 20, "q": "You haven't seen my mobile phone anywhere, have you?", "o": ["(A) I've been there before.", "(B) I'd check in the break room.", "(C) I don't know her number."], "a": "B", "zh": "你有在哪裡看到我的手機嗎？", "ozh": ["我以前去過那裡。", "我會去茶水間找找看。", "我不知道她的號碼。"], "audio": "Part2/C1/20.mp3"}, {"no": 21, "q": "Isn't the museum closed now?", "o": ["(A) Nine dollars.", "(B) Not too far.", "(C) Well, it is after nine."], "a": "C", "zh": "博物館現在不是關門了嗎？", "ozh": ["九美元。", "不太遠。", "也是啦，現在已經過九點了。"], "audio": "Part2/C1/21.mp3"}, {"no": 22, "q": "I can't reach the boxes on this top shelf.", "o": ["(A) Shall I get a ladder?", "(B) More packaging materials.", "(C) It stopped a while ago."], "a": "A", "zh": "我拿不到最上層架子上的箱子。", "ozh": ["需要我拿梯子過來嗎？", "更多包裝材料。", "不久前停了。"], "audio": "Part2/C1/22.mp3"}, {"no": 23, "q": "When will the safety inspector check the emergency exits?", "o": ["(A) Over there, on your right.", "(B) He'll be here on Tuesday.", "(C) He can't open the safe."], "a": "B", "zh": "安全檢查員什麼時候會檢查緊急出口？", "ozh": ["在那邊，你的右手邊。", "他週二會過來。", "他打不開保險箱。"], "audio": "Part2/C1/23.mp3"}, {"no": 24, "q": "Will the fliers be ready today, or do you need more time to finish them?", "o": ["(A) I'll start work on them now.", "(B) I don't know who's going.", "(C) Her flight's late."], "a": "A", "zh": "傳單今天會好，還是你需要更多時間完成？", "ozh": ["我現在開始製作。", "我不知道誰要去。", "她的班機晚點。"], "audio": "Part2/C1/24.mp3"}, {"no": 25, "q": "Didn't you submit an article to the business journal last month?", "o": ["(A) Why? Has it been published?", "(B) Can I renew it?", "(C) It's always been that way."], "a": "A", "zh": "你上個月不是向商業期刊投稿了一篇文章嗎？", "ozh": ["怎麼了？出版了嗎？", "我可以續訂嗎？", "一直都是那樣。"], "audio": "Part2/C1/25.mp3"}, {"no": 26, "q": "Do you have flowers for sale?", "o": ["(A) Birthdays and graduations.", "(B) I expect to have some soon.", "(C) Are those for me?"], "a": "B", "zh": "你們有賣花嗎？", "ozh": ["生日和畢業典禮。", "預計很快就會進貨。", "那些是給我的嗎？"], "audio": "Part2/C1/26.mp3"}, {"no": 27, "q": "Could you possibly change the time of the marketing meeting?", "o": ["(A) But Mr. Cho is only available this morning.", "(B) No, I've been to the market.", "(C) We had a great time."], "a": "A", "zh": "你能更改行銷會議的時間嗎？", "ozh": ["但趙先生今天早上才有空。", "不，我去過市場。", "我們玩得很高興。"], "audio": "Part2/C1/27.mp3"}, {"no": 28, "q": "Who'd like to volunteer to be a tour guide?", "o": ["(A) I've done it before.", "(B) That's very helpful.", "(C) Two weeks ago."], "a": "A", "zh": "誰想志願擔任導覽員？", "ozh": ["我以前做過。", "那非常有幫助。", "兩週以前。"], "audio": "Part2/C1/28.mp3"}, {"no": 29, "q": "Do you have this same T-shirt design, but in blue?", "o": ["(A) Thanks, I'll tell the designer.", "(B) We have it in purple.", "(C) To meet the company dress code."], "a": "B", "zh": "這款 T恤有藍色的嗎？", "ozh": ["謝謝，我會告訴設計師。", "我們有紫色的。", "為了符合公司穿著規範。"], "audio": "Part2/C1/29.mp3"}, {"no": 30, "q": "The rental car has been returned, hasn't it?", "o": ["(A) Thanks, I'm ready to order.", "(B) I did it myself.", "(C) Four hundred miles."], "a": "B", "zh": "租來的車已經還了吧？", "ozh": ["謝謝，我準備好點餐了。", "我親自去還的。", "四百英哩。"], "audio": "Part2/C1/30.mp3"}, {"no": 31, "q": "Why isn't the vegetable soup on your lunch menu today?", "o": ["(A) It suits you well.", "(B) The same amount of water.", "(C) We're offering French onion soup."], "a": "C", "zh": "為什麼今天的午餐菜單沒有蔬菜湯？", "ozh": ["很適合你。", "同樣的水量。", "我們今天提供法式洋蔥湯。"], "audio": "Part2/C1/31.mp3"}]});
PART2_EXAMS.push({"id": "C3", "label": "試卷 C3（逐題音檔）", "kind": "files", "dir": "Part2/C3", "directions": "Part2/C3/Part2 directions.mp3", "questions": [{"no": 7, "q": "When do you leave for Paris?", "o": ["(A) Late on Tuesday evening.", "(B) Leave it at the front desk.", "(C) She'll be gone."], "a": "A", "zh": "你什麼時候出發去巴黎？", "ozh": ["週二深夜。", "放在櫃檯。", "她會離開。"], "audio": "Part2/C3/7.mp3"}, {"no": 8, "q": "How long do these batteries last?", "o": ["(A) About six months.", "(B) Yes, last Monday.", "(C) Along that street."], "a": "A", "zh": "這些電池能用多久？", "ozh": ["大約六個月。", "對，上週一。", "沿著那條街。"], "audio": "Part2/C3/8.mp3"}, {"no": 9, "q": "Have you eaten here before?", "o": ["(A) No, it's my first time.", "(B) I'll wait until later.", "(C) Actually, there'll only be three."], "a": "A", "zh": "你以前在這裡吃過嗎？", "ozh": ["沒有，我第一次來。", "我晚點再等。", "實際上只會有三個人。"], "audio": "Part2/C3/9.mp3"}, {"no": 10, "q": "Which office is Kathy's?", "o": ["(A) Sure, I can do that.", "(B) The corner one.", "(C) She's very organized."], "a": "B", "zh": "哪一間是凱西的辦公室？", "ozh": ["好的，我可以做到。", "轉角那間。", "她很有條理。"], "audio": "Part2/C3/10.mp3"}, {"no": 11, "q": "Didn't Jay approve the expense report yesterday?", "o": ["(A) That's expensive.", "(B) No, he'll do it today.", "(C) I didn't try it on."], "a": "B", "zh": "傑伊昨天不是核准報銷單了嗎？", "ozh": ["好貴。", "沒有，他今天會審核。", "我沒試穿。"], "audio": "Part2/C3/11.mp3"}, {"no": 12, "q": "Where is the temperature control for this room?", "o": ["(A) Nearly four-thirty.", "(B) Some cold water.", "(C) Next to the door."], "a": "C", "zh": "這間房間的溫度開關在哪裡？", "ozh": ["快四點半。", "一些冷水。", "門旁邊。"], "audio": "Part2/C3/12.mp3"}, {"no": 13, "q": "Should I attach the price tags to the back of the items?", "o": ["(A) Yes, that would be great, thanks.", "(B) Sorry, all our sales are final.", "(C) It's near the discount table."], "a": "A", "zh": "我應該把標價籤貼在商品背面嗎？", "ozh": ["對，那太好了，謝謝。", "抱歉，特價售出不退。", "在折扣桌附近。"], "audio": "Part2/C3/13.mp3"}, {"no": 14, "q": "Do you know who's planning Jane's going-away party?", "o": ["(A) I think it's Tom Shields.", "(B) It's on the twenty-third.", "(C) No, he can't go."], "a": "A", "zh": "你知道誰在籌備簡的告別派對嗎？", "ozh": ["我想是湯姆·席爾斯。", "在二十三號。", "不，他去不了。"], "audio": "Part2/C3/14.mp3"}, {"no": 15, "q": "Dr. Lee gave you instructions for your medication, didn't she?", "o": ["(A) She said to take it twice a day.", "(B) To the Parkvale Clinic.", "(C) I feel rather tired."], "a": "A", "zh": "李醫生有交代你怎麼吃藥，對吧？", "ozh": ["她說每天吃兩次。", "去帕克維爾診所。", "我覺得滿累的。"], "audio": "Part2/C3/15.mp3"}, {"no": 16, "q": "Where should I put the large envelopes?", "o": ["(A) Yes, you should.", "(B) I'll order the small ones.", "(C) In the supply room, please."], "a": "C", "zh": "我該把大信封放在哪裡？", "ozh": ["對，你應該。", "我會訂小號的。", "請放進用品室。"], "audio": "Part2/C3/16.mp3"}, {"no": 17, "q": "Doesn't the computer come with that program already installed?", "o": ["(A) I don't have a television.", "(B) No, you have to download it from the Internet.", "(C) He usually comes on Mondays."], "a": "B", "zh": "這台電腦沒有預裝那個軟體嗎？", "ozh": ["我沒有電視。", "沒有，你必須從網路下載。", "他通常週一來。"], "audio": "Part2/C3/17.mp3"}, {"no": 18, "q": "How can I reserve one of the library's meeting rooms?", "o": ["(A) Let me get the librarian to help you with that.", "(B) They usually meet from three to four P.M.", "(C) That book's already checked out."], "a": "A", "zh": "我該如何預約圖書館的會議室？", "ozh": ["我請圖書館員幫你處理。", "他們通常下午三點到四點開會。", "那本書已經被借走了。"], "audio": "Part2/C3/18.mp3"}, {"no": 19, "q": "Who's involved in organizing the town festival?", "o": ["(A) Admission and activities are free.", "(B) It's on Saturday morning.", "(C) Oh, are you interested in helping out?"], "a": "C", "zh": "誰參與了城鎮節慶的組織籌備？", "ozh": ["入場和活動免費。", "在週六早上。", "噢，你有興趣幫忙嗎？"], "audio": "Part2/C3/19.mp3"}, {"no": 20, "q": "Does the train leave from Platform twenty-four or Platform twenty-five?", "o": ["(A) A window seat.", "(B) Let's check our tickets.", "(C) No, it's running on time."], "a": "B", "zh": "火車是在 24 月台還是 25 月台發車？", "ozh": ["靠窗座位。", "我們看一下車票吧。", "不，準時發車。"], "audio": "Part2/C3/20.mp3"}, {"no": 21, "q": "Do you have time for a quick football game?", "o": ["(A) Do you remember that one?", "(B) I have seen them play.", "(C) Should I bring my ball?"], "a": "C", "zh": "你有時間踢一場快速的足球賽嗎？", "ozh": ["你還記得那個嗎？", "我看過他們踢球。", "我要把足球帶去嗎？"], "audio": "Part2/C3/21.mp3"}, {"no": 22, "q": "There's a helpful diagram on page fifty-seven.", "o": ["(A) You're very welcome.", "(B) Mr. Evans did.", "(C) OK, I'll take a look."], "a": "C", "zh": "第五十七頁有一個很有幫助的圖表。", "ozh": ["不客氣。", "艾文斯先生做的。", "好的，我來看看。"], "audio": "Part2/C3/22.mp3"}, {"no": 23, "q": "Did you buy the coat online or from a shop?", "o": ["(A) I never buy clothes without trying them on.", "(B) Do you have this in a smaller size?", "(C) No, the line isn't very long."], "a": "A", "zh": "這件外套你是網購的還是在店裡買的？", "ozh": ["我買衣服一定要先試穿。", "這款有小一點的尺寸嗎？", "不，排隊的人不多。"], "audio": "Part2/C3/23.mp3"}, {"no": 24, "q": "Would you type up the minutes from today's staff meeting?", "o": ["(A) Sure, I'll have them ready by three o'clock.", "(B) There are a few other types, too.", "(C) Almost everyone in the office."], "a": "A", "zh": "你能打一下今天員工會議的紀錄嗎？", "ozh": ["沒問題，我三點前打好。", "還有其他幾種類型。", "辦公室幾乎所有人。"], "audio": "Part2/C3/24.mp3"}, {"no": 25, "q": "What are the best vegetarian restaurants in this area?", "o": ["(A) We open in an hour.", "(B) I'm not the best person to ask.", "(C) Outside seating is available."], "a": "B", "zh": "這附近最好的素食餐廳是哪家？", "ozh": ["我們一小時後開門。", "我不是最適合問的人。", "有戶外座位。"], "audio": "Part2/C3/25.mp3"}, {"no": 26, "q": "Why is the contractor coming in tomorrow?", "o": ["(A) I thought you asked him to come.", "(B) You have to initial every page.", "(C) At least three weeks."], "a": "A", "zh": "承包商明天為什麼要來？", "ozh": ["我以為是你叫他來的。", "你要在每一頁簽姓名縮寫。", "至少三週。"], "audio": "Part2/C3/26.mp3"}, {"no": 27, "q": "We sold fifteen laptop computers today, didn't we?", "o": ["(A) Our desktop computer is too old.", "(B) The store opened three years ago.", "(C) Yes, it was a good day."], "a": "C", "zh": "我們今天賣出了十五台筆記型電腦，對吧？", "ozh": ["我們的桌上型電腦太舊了。", "這家店三年前開張。", "對啊，今天是豐收的一天。"], "audio": "Part2/C3/27.mp3"}, {"no": 28, "q": "I'd like to discuss the project you just turned in.", "o": ["(A) We just purchased that projector.", "(B) Not very often.", "(C) Could it wait until tomorrow?"], "a": "C", "zh": "我想討論你剛交上來的專案。", "ozh": ["我們剛買了那台投影機。", "不太常。", "能等到明天再討論嗎？"], "audio": "Part2/C3/28.mp3"}, {"no": 29, "q": "Shall I show you how to make the font size larger?", "o": ["(A) It is hard to read at this size.", "(B) Sure, I'd love to go.", "(C) Thanks for the letter."], "a": "A", "zh": "要我教你怎麼把字型放大嗎？", "ozh": ["這個大小確實很難讀。", "當然，我很樂意去。", "謝謝你的來信。"], "audio": "Part2/C3/29.mp3"}, {"no": 30, "q": "When will the labeling machine be repaired?", "o": ["(A) Yes, you should work in pairs.", "(B) The list of ingredients is on the label.", "(C) They still don't know what's wrong with it."], "a": "C", "zh": "標籤機什麼時候會修好？", "ozh": ["對，你們應該兩人一組。", "成份表在標籤上。", "他們還不知道哪裡壞了。"], "audio": "Part2/C3/30.mp3"}, {"no": 31, "q": "Should we invite more staff to attend the trade show?", "o": ["(A) We're not sure about hiring him.", "(B) I don't think it's necessary.", "(C) From New York to Sydney."], "a": "B", "zh": "我們應該邀請更多員工參加商展嗎？", "ozh": ["我們不確定要不要僱用他。", "我覺得沒必要。", "從紐約到雪梨。"], "audio": "Part2/C3/31.mp3"}]});
PART2_EXAMS.push({"id": "D1", "label": "試卷 D1（逐題音檔）", "kind": "files", "dir": "Part2/D1", "directions": "Part2/D1/Part2 directions.mp3", "questions": [{"no": 7, "q": "Where can I find the most recent sales data?", "o": ["(A) The store's having a sale.", "(B) It's on my computer.", "(C) No, not recently."], "a": "B", "zh": "我可以在哪裡找到最新的銷售數據？", "ozh": ["商店在搞特賣。", "在我的電腦裡。", "不，最近沒有。"], "audio": "Part2/D1/7.mp3"}, {"no": 8, "q": "When is the next performance of the City Dance Troupe?", "o": ["(A) This Saturday at eight P.M.", "(B) It was better than the last one.", "(C) It hasn't yet."], "a": "A", "zh": "城市舞團的下一場演出是什麼時候？", "ozh": ["本週六晚間八點。", "比上一場好。", "還沒有。"], "audio": "Part2/D1/8.mp3"}, {"no": 9, "q": "Let's plan our camping trip tonight.", "o": ["(A) I had a relaxing vacation.", "(B) OK, I'm free after six.", "(C) A tent and a sleeping bag."], "a": "B", "zh": "我們今晚來規劃露營行程吧。", "ozh": ["我度過了一個放鬆的假期。", "好的，我六點後有空。", "帳篷和睡袋。"], "audio": "Part2/D1/9.mp3"}, {"no": 10, "q": "Isn't the client visit this month?", "o": ["(A) It's in the supply cabinet.", "(B) A newer version.", "(C) Pablo's in charge of that."], "a": "C", "zh": "客戶拜訪不是這個月嗎？", "ozh": ["在用品櫃裡。", "較新的版本。", "Pablo 負責該業務。"], "audio": "Part2/D1/10.mp3"}, {"no": 11, "q": "Why are you transferring to the San Francisco branch?", "o": ["(A) To be closer to my family.", "(B) Probably in February.", "(C) Yes, it's been open for a while."], "a": "A", "zh": "你為什麼要調去舊金山分公司？", "ozh": ["為了離家人近一點。", "可能在二月。", "對，已經開了一陣子。"], "audio": "Part2/D1/11.mp3"}, {"no": 12, "q": "Do you have any hotel rooms available for tonight?", "o": ["(A) They're due soon.", "(B) Almost every room has one.", "(C) We've just had a cancellation!"], "a": "C", "zh": "你們今晚還有空房嗎？", "ozh": ["他們快到期了。", "幾乎每間房都有。", "剛好有人取消訂房！"], "audio": "Part2/D1/12.mp3"}, {"no": 13, "q": "Would you like me to arrange a shuttle to the airport?", "o": ["(A) That flower arrangement is lovely.", "(B) Thanks, but I'll drive myself there.", "(C) A glass of water would be great."], "a": "B", "zh": "需要我幫你安排去機場的接駁車嗎？", "ozh": ["插花很漂亮。", "謝謝，但我會自己開車去。", "一杯水太棒了。"], "audio": "Part2/D1/13.mp3"}, {"no": 14, "q": "Does Marta know that we've made a lunch reservation for one o'clock?", "o": ["(A) Yes, I sent her an e-mail about it.", "(B) The Town Plaza Café.", "(C) It's served with a side salad."], "a": "A", "zh": "瑪塔知道我們訂了一點的午餐嗎？", "ozh": ["知道，我有發電子郵件給她。", "城鎮廣場咖啡館。", "附贈側邊沙拉。"], "audio": "Part2/D1/14.mp3"}, {"no": 15, "q": "Who should I contact to rent an office in this building?", "o": ["(A) Yes, I'll update my contact list.", "(B) You can call Mr. Yamamoto.", "(C) The one in the financial center."], "a": "B", "zh": "想在這棟大樓租辦公室該聯絡誰？", "ozh": ["對，我會更新聯絡名單。", "你可以打給山本先生。", "金融中心那間。"], "audio": "Part2/D1/15.mp3"}, {"no": 16, "q": "What did you think of my presentation?", "o": ["(A) No, not this time.", "(B) I was at another meeting.", "(C) Twenty pages long."], "a": "B", "zh": "你覺得我的簡報怎麼樣？", "ozh": ["不，這次沒有。", "我當時在開另一個會。", "二十頁長。"], "audio": "Part2/D1/16.mp3"}, {"no": 17, "q": "When will our Internet service be working again?", "o": ["(A) No, I don't use it often.", "(B) It should be fixed by noon.", "(C) Over by the copier."], "a": "B", "zh": "我們的網路什麼時候會恢復正常？", "ozh": ["不，我不常使用。", "中午以前應該會修好。", "在影印機那邊。"], "audio": "Part2/D1/17.mp3"}, {"no": 18, "q": "Have you finished the draft of the report yet?", "o": ["(A) I had a conference call all morning.", "(B) Ms. Yang is a reporter.", "(C) Thanks, I can wait."], "a": "A", "zh": "你完成報告初稿了嗎？", "ozh": ["我整個早上都在開電話會議。", "楊女士是記者。", "謝謝，我可以等。"], "audio": "Part2/D1/18.mp3"}, {"no": 19, "q": "You didn't leave your mobile phone on the train, did you?", "o": ["(A) It's 555-0126.", "(B) A ticket to Amsterdam.", "(C) No, I have it right here."], "a": "C", "zh": "你沒把手機忘在火車上吧？", "ozh": ["是 555-0126。", "去阿姆斯特丹的車票。", "沒有，我拿在手上。"], "audio": "Part2/D1/19.mp3"}, {"no": 20, "q": "Could you please replace the tires on my car?", "o": ["(A) He's retiring in May.", "(B) That's a very nice place.", "(C) Yes, we could do it this afternoon."], "a": "C", "zh": "能幫我更換車子的輪胎嗎？", "ozh": ["他五月退休。", "那是個很棒的地方。", "可以，我們今天下午處理。"], "audio": "Part2/D1/20.mp3"}, {"no": 21, "q": "What time should we expect the keynote speaker to arrive?", "o": ["(A) She'll be here by nine.", "(B) Yes, I was invited.", "(C) In the lobby."], "a": "A", "zh": "主講人預計幾點抵達？", "ozh": ["她九點前會到。", "對，我有被邀請。", "在大廳。"], "audio": "Part2/D1/21.mp3"}, {"no": 22, "q": "Did you hear the news about the merger?", "o": ["(A) A small construction firm.", "(B) No, was it announced?", "(C) He's a department head."], "a": "B", "zh": "你有聽到併購的消息嗎？", "ozh": ["小型營造公司。", "沒有，公布了嗎？", "他是部門主管。"], "audio": "Part2/D1/22.mp3"}, {"no": 23, "q": "Does our budget include funding for one assistant or two?", "o": ["(A) I didn't know we were hiring anyone.", "(B) At the reception desk.", "(C) It was paid for in cash."], "a": "A", "zh": "我們的預算有包含一名還是兩名助理的費用？", "ozh": ["我不知道我們要請人。", "在接待處。", "用現金支付。"], "audio": "Part2/D1/23.mp3"}, {"no": 24, "q": "That Indian restaurant is big enough for our annual party.", "o": ["(A) They don't have a private dining room.", "(B) A direct flight to India.", "(C) Can I get you some more rice?"], "a": "A", "zh": "那家印度餐廳夠大，容得下我們的年度派對。", "ozh": ["他們沒有獨立包廂。", "直飛印度航班。", "需要再加飯嗎？"], "audio": "Part2/D1/24.mp3"}, {"no": 25, "q": "Is there a computer available to use while mine is being repaired?", "o": ["(A) Isn't it in two hours?", "(B) Michael's not using his today.", "(C) Some updated software."], "a": "B", "zh": "在我的電腦維修期間有電腦可用嗎？", "ozh": ["不是兩小時內嗎？", "麥克今天沒用他的電腦。", "一些更新的軟體。"], "audio": "Part2/D1/25.mp3"}, {"no": 26, "q": "Will you prepare handouts or a slide show for your workshop?", "o": ["(A) Just the new sales director.", "(B) I plan to do both.", "(C) It starts at three o'clock."], "a": "B", "zh": "你工作坊會準備講義還是簡報？", "ozh": ["只有新銷售總監。", "我打算兩個都準備。", "三點開始。"], "audio": "Part2/D1/26.mp3"}, {"no": 27, "q": "The meeting's in Busan, isn't it?", "o": ["(A) It isn't a company I've heard of.", "(B) Yes—I hope we can participate by phone.", "(C) The attendance sheet."], "a": "B", "zh": "會議是在釜山舉行，對吧？", "ozh": ["我沒聽說過這家公司。", "對—希望我們能電話連線參加。", "出席表。"], "audio": "Part2/D1/27.mp3"}, {"no": 28, "q": "Can you give me a tour of the property on Thursday?", "o": ["(A) An empty corner lot.", "(B) Leave the door open.", "(C) Let me check my calendar."], "a": "C", "zh": "週四你能帶我參觀這處房產嗎？", "ozh": ["空置的轉角地。", "門開著。", "我看一下我的行事曆。"], "audio": "Part2/D1/28.mp3"}, {"no": 29, "q": "How many days do we have to organize the convention?", "o": ["(A) There are three hundred brochures.", "(B) Don't worry, it's later than last year.", "(C) We'll choose the cheapest one."], "a": "B", "zh": "我們有多少天可以籌備大會？", "ozh": ["有三百本小冊子。", "別擔心，比去年晚辦。", "我們會選最便宜的。"], "audio": "Part2/D1/29.mp3"}, {"no": 30, "q": "I don't think we can afford to start the store renovations yet.", "o": ["(A) That's not what Susan said.", "(B) Yes, it's attracting more customers.", "(C) The product display areas."], "a": "A", "zh": "我覺得我們現在還負擔不起店面整修的費用。", "ozh": ["蘇珊可不是這麼說的。", "對，吸引了更多顧客。", "產品展示區。"], "audio": "Part2/D1/30.mp3"}, {"no": 31, "q": "We've met these clients before, haven't we?", "o": ["(A) Sure, I'd be happy to.", "(B) Actually, we shipped them already.", "(C) The manager is new, though."], "a": "C", "zh": "我們以前看過這些客戶，不是嗎？", "ozh": ["當然，我很高興。", "實際上我們已經發貨了。", "不過經理是新來的。"], "audio": "Part2/D1/31.mp3"}]});
PART2_EXAMS.push({"id": "D3", "label": "試卷 D3（逐題音檔）", "kind": "files", "dir": "Part2/D3", "directions": "Part2/D3/Part2 directions.mp3", "questions": [{"no": 7, "q": "When does the shuttle bus leave for the airport?", "o": ["(A) Every hour on the hour.", "(B) In the hotel lobby.", "(C) Twelve dollars."], "a": "A", "zh": "去機場的接駁車什麼時候發車？", "ozh": ["每逢整點發車。", "在飯店大廳。", "十二美元。"], "audio": "Part2/D3/7.mp3"}, {"no": 8, "q": "Where can I find the printer?", "o": ["(A) Thirty pages at a time.", "(B) Monday to Friday.", "(C) Down the hall to your left."], "a": "C", "zh": "印表機在哪裡？", "ozh": ["一次三十頁。", "週一到週五。", "走廊底左手邊。"], "audio": "Part2/D3/8.mp3"}, {"no": 9, "q": "Who will be going to the exposition this year?", "o": ["(A) It was a good experience.", "(B) Several of our colleagues.", "(C) The beginning of October."], "a": "B", "zh": "今年誰會去博覽會？", "ozh": ["那是一次很好的體驗。", "我們的幾位同事。", "十月初。"], "audio": "Part2/D3/9.mp3"}, {"no": 10, "q": "Would you like me to bring you another soft drink?", "o": ["(A) That's OK, I don't want one.", "(B) No, that's the first time I've heard it.", "(C) The dinner reservation's at eight."], "a": "A", "zh": "需要我幫你拿另一杯軟性飲料嗎？", "ozh": ["不用了，我不需要。", "沒有，這是我第一次聽說。", "晚餐預約在八點。"], "audio": "Part2/D3/10.mp3"}, {"no": 11, "q": "Is Maria going to present the sales report, or are you doing it?", "o": ["(A) We're doing it together.", "(B) It's on sale today.", "(C) In a couple of weeks."], "a": "A", "zh": "瑪麗亞要報告銷售報告，還是由你報告？", "ozh": ["我們要一起報告。", "今天有特價。", "幾週內。"], "audio": "Part2/D3/11.mp3"}, {"no": 12, "q": "What's the name of the new intern in the design department?", "o": ["(A) I think it's Sammy, but I'm not sure.", "(B) We sent in the blueprint.", "(C) Yes, I enjoyed the internship."], "a": "A", "zh": "設計部新實習生叫什麼名字？", "ozh": ["我想是薩米，但我不確定。", "我們寄出了藍圖。", "對，我很享受實習。"], "audio": "Part2/D3/12.mp3"}, {"no": 13, "q": "Are you ready for your next patient?", "o": ["(A) Usually thirty minutes.", "(B) I already read it.", "(C) Sure, send her in."], "a": "C", "zh": "你準備好接見下一位病人了嗎？", "ozh": ["通常三十分鐘。", "我已經讀過了。", "當然，請她進來。"], "audio": "Part2/D3/13.mp3"}, {"no": 14, "q": "How do you turn the packaging machine on?", "o": ["(A) Next to the storage area.", "(B) Push the green button.", "(C) No, I haven't seen her."], "a": "B", "zh": "包裝機要怎麼開？", "ozh": ["儲藏區旁邊。", "按下綠色按鈕。", "不，我沒看到她。"], "audio": "Part2/D3/14.mp3"}, {"no": 15, "q": "You went to the soccer match last week, didn't you?", "o": ["(A) These socks don't match.", "(B) A local sports writer.", "(C) I did—my favorite team won!"], "a": "C", "zh": "你上週去了足球比賽，對吧？", "ozh": ["這雙襪子不搭配。", "當地體育記者。", "對啊—我最喜歡的球隊贏了！"], "audio": "Part2/D3/15.mp3"}, {"no": 16, "q": "Will you stay after the show to meet the musicians?", "o": ["(A) I think so too.", "(B) Almost as long as the previous show.", "(C) Don't they leave as soon as it's over?"], "a": "C", "zh": "演出結束後你會留下來見音樂家嗎？", "ozh": ["我也這麼認為。", "幾乎和上一場一樣長。", "他們不是結束後就馬上離開了嗎？"], "audio": "Part2/D3/16.mp3"}, {"no": 17, "q": "How often do you buy new glasses?", "o": ["(A) About three to five days per order.", "(B) The store on Robin Street.", "(C) I actually switched to contact lenses."], "a": "C", "zh": "你多久買一次新眼鏡？", "ozh": ["每次訂單約三到五天。", "羅賓街上的那家店。", "我其實改戴隱形眼鏡了。"], "audio": "Part2/D3/17.mp3"}, {"no": 18, "q": "Didn't the clients say they'd prefer to tour the factory today?", "o": ["(A) A job application.", "(B) Their schedule is already full.", "(C) It's a new building."], "a": "B", "zh": "客戶不是說今天比較想參觀工廠嗎？", "ozh": ["求職申請。", "他們的行程已經排滿了。", "那是一棟新大樓。"], "audio": "Part2/D3/18.mp3"}, {"no": 19, "q": "I can pick up your packages while I'm at the post office.", "o": ["(A) Thanks, but I already got them.", "(B) I picked the cheapest one.", "(C) Did you send it through the mail?"], "a": "A", "zh": "我去郵局時可以順便幫你拿包裹。", "ozh": ["謝謝，但我已經拿到了。", "我挑了最便宜的。", "你是用郵寄的嗎？"], "audio": "Part2/D3/19.mp3"}, {"no": 20, "q": "Which page should I turn to in the manual?", "o": ["(A) Make a left just past that stop sign.", "(B) Wait, that's the wrong manual.", "(C) Maybe several hours ago."], "a": "B", "zh": "手冊我應該翻到哪一頁？", "ozh": ["過了停標誌後左轉。", "等等，拿錯本手冊了。", "大約幾個小時前。"], "audio": "Part2/D3/20.mp3"}, {"no": 21, "q": "Where are your photographs being exhibited now?", "o": ["(A) Only in black and white.", "(B) At the community center.", "(C) Almost a month."], "a": "B", "zh": "你的攝影作品現在在哪裡展出？", "ozh": ["只有黑白照片。", "在社區中心。", "幾乎一個月。"], "audio": "Part2/D3/21.mp3"}, {"no": 22, "q": "This database could be more user-friendly.", "o": ["(A) More than five hundred surveys.", "(B) We're working on updates right now.", "(C) Choose a new user name and password."], "a": "B", "zh": "這個資料庫可以設計得更方便使用。", "ozh": ["五百多份問卷。", "我們現在正在進行更新。", "選擇新的使用者名稱和密碼。"], "audio": "Part2/D3/22.mp3"}, {"no": 23, "q": "When did your company start importing steel?", "o": ["(A) A nineteen percent increase.", "(B) Central and South America, mostly.", "(C) I'd have to check our records."], "a": "C", "zh": "你們公司什麼時候開始進口鋼鐵的？", "ozh": ["百分之十九的成長。", "主要是在中南美洲。", "我必須查一下我們的紀錄。"], "audio": "Part2/D3/23.mp3"}, {"no": 24, "q": "We found some defects in the accounting software.", "o": ["(A) That's unfortunate.", "(B) He's on the third floor.", "(C) The bank canceled it."], "a": "A", "zh": "我們在會計軟體中發現了一些缺陷。", "ozh": ["那真是不幸。", "他在三樓。", "銀行取消了。"], "audio": "Part2/D3/24.mp3"}, {"no": 25, "q": "Why didn't you take the bus today?", "o": ["(A) Outside my apartment.", "(B) Because Wendy drove me.", "(C) A three-day workshop."], "a": "B", "zh": "你今天為什麼沒坐公車？", "ozh": ["我公寓外面。", "因為溫蒂開車載我。", "為期三天的工作坊。"], "audio": "Part2/D3/25.mp3"}, {"no": 26, "q": "We can have the replacement parts by Friday, right?", "o": ["(A) Put it on the lowest shelf.", "(B) Yes—but shipping costs more.", "(C) No, at the next traffic light."], "a": "B", "zh": "我們週五前能收到替換零件，對吧？", "ozh": ["把它放在最下層架子上。", "對—但運費比較貴。", "不，在下個紅綠燈。"], "audio": "Part2/D3/26.mp3"}, {"no": 27, "q": "The CEO's presentation is in Conference Room C.", "o": ["(A) This book makes a great present.", "(B) Oh—I was headed the wrong way.", "(C) On the last page."], "a": "B", "zh": "執行長的簡報在 C 會議室。", "ozh": ["這本書很適合當禮物。", "噢—我走錯方向了。", "在最後一頁。"], "audio": "Part2/D3/27.mp3"}, {"no": 28, "q": "Isn't the gym open twenty-four hours?", "o": ["(A) Only on the weekend.", "(B) Yes, she's really helpful.", "(C) That's when it's due."], "a": "A", "zh": "健身房不是二十四小時營業嗎？", "ozh": ["只有週末才是。", "對，她很有幫助。", "那是到期的時間。"], "audio": "Part2/D3/28.mp3"}, {"no": 29, "q": "Why are we starting with training module four?", "o": ["(A) At the top of page 112.", "(B) I'd prefer a later time if possible.", "(C) This is the advanced session."], "a": "C", "zh": "我們為什麼要從第四訓練模組開始？", "ozh": ["在第 112 頁頂端。", "如果可以我想選晚一點的時間。", "因為這是進階場次。"], "audio": "Part2/D3/29.mp3"}, {"no": 30, "q": "Who's organizing this month's book club meeting?", "o": ["(A) At the library, of course.", "(B) I did it last time.", "(C) It's a best seller."], "a": "B", "zh": "誰在籌辦這個月的讀書會會議？", "ozh": ["當然在圖書館。", "上次是我辦的。", "這是暢銷書。"], "audio": "Part2/D3/30.mp3"}, {"no": 31, "q": "Let's look at some rental properties today.", "o": ["(A) I'll have more time tomorrow.", "(B) Oh, congratulations!", "(C) I think it was Carla."], "a": "A", "zh": "我們今天來看一些租賃房產吧。", "ozh": ["我明天時間比較充裕。", "噢，恭喜！", "我想是卡拉。"], "audio": "Part2/D3/31.mp3"}]});
PART2_EXAMS.push({"id": "A-3", "label": "整份音檔 A-3", "kind": "whole", "file": "Part2/New TOEIC A-3.mp3", "starts": [27.93, 46.38, 63.12, 81.24, 101.3, 119.29, 138.06, 157.17, 175.31, 194.12, 213.43, 233.5, 252.5, 272.29, 292.17, 312.25, 330.98, 351.74, 370.17, 390.75, 410.62, 429.89, 450.65, 472.68, 493.43], "ends": [41.28, 57.98, 76.11, 96.2, 114.19, 133.0, 152.01, 170.23, 189.05, 208.32, 228.42, 247.4, 267.19, 287.01, 307.15, 325.84, 346.61, 365.09, 385.61, 405.45, 424.72, 445.54, 467.49, 488.3, 508.93], "questions": [{"no": 7, "q": "Will you translate an e-mail into Spanish for me?", "o": ["(A) Three more chapters.", "(B) No, I haven't sent it yet?", "(C) Sure, let me see it."], "a": "C", "zh": "你願意幫我把這封電子郵件翻譯成西班牙文嗎？", "ozh": ["再三章。", "不，我還沒寄出。", "當然，拿給我看。"]}, {"no": 8, "q": "How many tables did you reserve?", "o": ["(A) Twelve of them.", "(B) I'll be right there.", "(C) For the awards dinner."], "a": "A", "zh": "你預訂了幾張桌子？", "ozh": ["十二張。", "我馬上到。", "為了頒獎晚宴。"]}, {"no": 9, "q": "Where can I mail this letter?", "o": ["(A) I don't have an envelope.", "(B) At the post office down the street.", "(C) No, not right now."], "a": "B", "zh": "我可以在哪裡寄這封信？", "ozh": ["我沒有信封。", "沿著這條街走的那間郵局。", "不，現在不行。"]}, {"no": 10, "q": "Why did you come to the office early today?", "o": ["(A) Because I had to finish a report.", "(B) Usually at eight-thirty in the morning.", "(C) I'm sorry, but I can't."], "a": "A", "zh": "你今天為什麼這麼早來辦公室？", "ozh": ["因為我必須完成一份報告。", "通常在早上八點半。", "很抱歉，但我辦不到。"]}, {"no": 11, "q": "Have you opened the front entrance yet?", "o": ["(A) I left it in the back.", "(B) I saw them.", "(C) No. I don't have a key."], "a": "C", "zh": "你開前門了嗎？", "ozh": ["我把它放在後面。", "我看到他們了。", "還沒，我沒有鑰匙。"]}, {"no": 12, "q": "You went to that museum last weekend, didn't you?", "o": ["(A) I saw him on Sunday.", "(B) I didn't have time.", "(C) For a few months."], "a": "B", "zh": "你上週末去那家博物館了，對吧？", "ozh": ["我週日看到他。", "我沒時間去。", "長達幾個月。"]}, {"no": 13, "q": "How many interns do we need this summer?", "o": ["(A) I think five will be enough.", "(B) We'll place an advertisement.", "(C) I'm well, thank you."], "a": "A", "zh": "我們今年夏天需要多少名實習生？", "ozh": ["我想五名就夠了。", "我們會刊登廣告。", "我很好，謝謝你。"]}, {"no": 14, "q": "What shift are you working on Saturday?", "o": ["(A) The morning one.", "(B) I can meet you there.", "(C) Yes, we booked it in April."], "a": "A", "zh": "你週六值什麼班？", "ozh": ["早班。", "我可以在那裡跟你會合。", "是的，我們四月預訂的。"]}, {"no": 15, "q": "My coworkers and I are going out for lunch tomorrow.", "o": ["(A) It launched at three.", "(B) I had the chicken.", "(C) That sounds nice."], "a": "C", "zh": "我和同事明天要出去吃午餐。", "ozh": ["它在三點推出。", "我點了雞肉。", "聽起來很棒。"]}, {"no": 16, "q": "When does the plane to Seoul leave?", "o": ["(A) No, I've never been.", "(B) It's an hour behind schedule.", "(C) From Gate 52, I think."], "a": "B", "zh": "飛往首爾的班機什麼時候起飛？", "ozh": ["不，我從未去過。", "延誤了一小時。", "我想是在52號登機門。"]}, {"no": 17, "q": "How will I know if the baseball game is canceled?", "o": ["(A) You could look on the team's Web site.", "(B) Yes, I knew that.", "(C) Because you chose a different date."], "a": "A", "zh": "我怎麼知道棒球賽是否取消？", "ozh": ["你可以查看球隊網站。", "是的，我知道。", "因為你選擇了不同的日期。"]}, {"no": 18, "q": "Should we get the changes to this agreement in writing?", "o": ["(A) Sorry, I don't have change.", "(B) That's probably a good idea.", "(C) I'll write each day."], "a": "B", "zh": "我們應該把這份協議的變更寫成書面形式嗎？", "ozh": ["抱歉，我沒有零錢。", "那大概是個好主意。", "我每天都會寫。"]}, {"no": 19, "q": "Will you create a chart to track our expenses this quarter?", "o": ["(A) Yeah, I'll do that now.", "(B) A quarterly fee.", "(C) Try track 46."], "a": "A", "zh": "你願意製作一個圖表來追蹤我們這一季的支出嗎？", "ozh": ["好的，我現在就做。", "按季收取的費用。", "試試46號跑道/音軌。"]}, {"no": 20, "q": "Where can I donate some old office equipment?", "o": ["(A) Because it starts at nine o'clock.", "(B) No, don't eat in here.", "(C) What kind of equipment is it?"], "a": "C", "zh": "我可以在哪裡捐贈一些舊的辦公設備？", "ozh": ["因為九點開始。", "不，不要在這裡吃東西。", "是哪種設備？"]}, {"no": 21, "q": "I'll lose my registration fee if I can't attend the workshop, right?", "o": ["(A) I'm afraid so.", "(B) Just over there, on the right.", "(C) Check the lost and found."], "a": "A", "zh": "如果我無法參加工作坊，我的報名費就拿不回來了，對吧？", "ozh": ["恐怕是這樣。", "就在那邊，右邊。", "查看失物招領處。"]}, {"no": 22, "q": "Didn't Daniel accept the job offer?", "o": ["(A) He'll let us know tomorrow.", "(B) We expect a large crowd.", "(C) Yes, I will."], "a": "A", "zh": "丹尼爾沒有接受那份工作邀約嗎？", "ozh": ["他明天會通知我們。", "我們預計會有很大群的人。", "是的，我會的。"]}, {"no": 23, "q": "That building's still under construction, isn't it?", "o": ["(A) Maybe the site manager.", "(B) Yes, it's due to be finished in October.", "(C) Yes, it's on level six."], "a": "B", "zh": "那棟建築仍在施工中，對吧？", "ozh": ["也許是工地經理。", "對，預計十月竣工。", "對，在六樓。"]}, {"no": 24, "q": "Have we changed our paper supplier?", "o": ["(A) A large inventory.", "(B) I'm not sure.", "(C) In the cupboard there."], "a": "B", "zh": "我們更換紙張供應商了嗎？", "ozh": ["大量庫存。", "我不太確定。", "在那邊的櫥櫃裡。"]}, {"no": 25, "q": "Who's exhibiting in the Central Art Gallery next month?", "o": ["(A) Yes, it opens at seven P.M.", "(B) My friend Aziz is coming too.", "(C) It's a group of young Japanese artists."], "a": "C", "zh": "下個月誰會在中央美術館參展？", "ozh": ["是的，下午七點開放。", "我的朋友阿齊茲也會來。", "是一群日本年輕藝術家。"]}, {"no": 26, "q": "Shall we repaint the lobby or the boardroom?", "o": ["(A) There's some in the closet.", "(B) It has plenty of room.", "(C) We can afford to do both."], "a": "C", "zh": "我們應該重新裝潢大廳還是董事會會議室？", "ozh": ["璧櫥裡有一些。", "空間很大。", "我們有負擔兩者皆做的預算。"]}, {"no": 27, "q": "Are you riding your bike to work today?", "o": ["(A) Alfonso's writing the book.", "(B) Only if the weather's nice.", "(C) Yes, I'd like to work there."], "a": "B", "zh": "你今天騎自行車上班嗎？", "ozh": ["阿方索正在寫那本書。", "只有天氣好才騎。", "是的，我想在那裡工作。"]}, {"no": 28, "q": "When do you think we'll hear if we've won the Jones account?", "o": ["(A) I lost my accounting manual.", "(B) One of our biggest clients.", "(C) Ms. Watson might already know."], "a": "C", "zh": "你認為我們什麼時候會得知是否拿下瓊斯公司的合約？", "ozh": ["我弄丟了會計手冊。", "我們最大的客戶之一。", "華生女士可能已經知道了。"]}, {"no": 29, "q": "You'd better call the technician to repair the photocopier.", "o": ["(A) Yes, overnight delivery.", "(B) Hopefully it won't take him too long.", "(C) Double-sided copies, please."], "a": "B", "zh": "你最好叫技術人員來維修影印機。", "ozh": ["是的，隔夜送達。", "希望不會花他太長時間。", "請雙面影印。"]}, {"no": 30, "q": "I don't know which computer model to buy.", "o": ["(A) What features are most important to you?", "(B) Because mine stopped working.", "(C) No, I won't get it for a while."], "a": "A", "zh": "我不知道該買哪款電腦型號。", "ozh": ["對你來說哪些功能最重要？", "因為我的電腦壞了。", "不，我一時半刻還不會買。"]}, {"no": 31, "q": "Didn't you see the review of our restaurant?", "o": ["(A) I haven't had time to read it yet.", "(B) There's a great view from the dining room.", "(C) A reservation for lunch on Saturday."], "a": "A", "zh": "你沒看到我們餐廳的評論嗎？", "ozh": ["我還沒時間看。", "餐廳看出去的景色非常好。", "預訂週六的午餐。"]}]});
PART2_EXAMS.push({"id": "A-9", "label": "整份音檔 A-9", "kind": "whole", "file": "Part2/New TOEIC A-9.mp3", "starts": [28.35, 48.08, 68.34, 88.16, 107.58, 128.56, 148.54, 170.55, 192.34, 214.32, 233.59, 253.94, 274.16, 295.42, 315.95, 336.39, 356.64, 378.0, 399.14, 421.15, 442.45, 463.56, 483.23, 504.6, 526.74], "ends": [42.6, 62.83, 82.7, 102.11, 123.15, 143.21, 165.16, 186.87, 208.95, 228.16, 248.46, 268.74, 290.03, 310.49, 330.93, 351.21, 372.58, 393.7, 415.73, 437.0, 458.16, 477.85, 499.11, 521.29, 542.28], "questions": [{"no": 7, "q": "Where can I find the most recent sales data?", "o": ["(A) The store's having a sale.", "(B) It's on my computer.", "(C) No, not recently."], "a": "B", "zh": "我在哪裡可以找到最新的銷售數據？", "ozh": ["店裡正在特賣。", "在我的電腦裡。", "不，最近沒有。"]}, {"no": 8, "q": "When is the next performance of the City Dance Troupe?", "o": ["(A) This Saturday at eight p.m.", "(B) It was better than the last one.", "(C) It hasn't yet."], "a": "A", "zh": "城市舞團下一次演出是什麼時候？", "ozh": ["這週六晚上八點。", "比上次好。", "還沒有。"]}, {"no": 9, "q": "Let's plan our camping trip tonight.", "o": ["(A) I had a relaxing vacation.", "(B) OK, I'm free after six.", "(C) A tent and a sleeping bag."], "a": "B", "zh": "我們今晚來規劃露營行程吧。", "ozh": ["我過了一個放鬆的假期。", "好的，我六點後有空。", "帳篷和睡袋。"]}, {"no": 10, "q": "Isn't the client visit this month?", "o": ["(A) It's in the supply cabinet.", "(B) A newer Version.", "(C) Pablo's in charge of that."], "a": "C", "zh": "客戶拜訪不是在這個月嗎？", "ozh": ["在用品櫃裡。", "較新的版本。", "巴布羅負責那件事。"]}, {"no": 11, "q": "Why are you transferring to the San Francisco branch?", "o": ["(A) To be closer to my family.", "(B) Probably in February.", "(C) Yes, it's been open for a while."], "a": "A", "zh": "你為什麼要調到舊金山分公司？", "ozh": ["為了離家人近一點。", "大概在二月。", "是的，已經開了一陣子了。"]}, {"no": 12, "q": "Do you have any hotel rooms available for tonight?", "o": ["(A) They're due soon.", "(B) Almost every room has one.", "(C) We've just had a cancellation!"], "a": "C", "zh": "你們今晚還有空房嗎？", "ozh": ["它們很快就到期了。", "幾乎每間房間都有。", "我們剛剛剛好有一筆取消預訂！"]}, {"no": 13, "q": "Would you like me to arrange a shuttle to the airport?", "o": ["(A) That flower arrangement is lovely.", "(B) Thanks, but I'll drive myself there.", "(C) A glass of water would be great."], "a": "B", "zh": "需要我幫你安排接駁車去機場嗎？", "ozh": ["那插花很漂亮。", "謝謝，但我會自己開車去。", "一杯水就太好了。"]}, {"no": 14, "q": "Does Marta know that we've made a lunch reservation for one o'clock?", "o": ["(A) Yes, I sent her an e-mail about it.", "(B) The Town Plaza Cafe.", "(C) It's served with a side salad."], "a": "A", "zh": "瑪爾塔知道我們預訂了一點的午餐嗎？", "ozh": ["知道，我有寄電子郵件通知她。", "城鎮廣場咖啡廳。", "附贈一份沙拉。"]}, {"no": 15, "q": "Who should I contact to rent an office in this building?", "o": ["(A) Yes, I'll update my contact list.", "(B) You can call Mr. Yamamoto.", "(C) The one in the financial center."], "a": "B", "zh": "我想在這棟大樓租辦公室應該聯絡誰？", "ozh": ["好，我會更新聯絡名單。", "你可以打給山本先生。", "金融中心的那一個。"]}, {"no": 16, "q": "What did you think of my presentation?", "o": ["(A) No, not this time.", "(B) I was at another meeting.", "(C) Twenty pages long."], "a": "B", "zh": "你覺得我的簡報做得怎麼樣？", "ozh": ["不，這次沒有。", "我當時在開另一個會。", "二十頁長。"]}, {"no": 17, "q": "When will our Internet service be working again?", "o": ["(A) No, I don't use it often.", "(B) It should be fixed by noon.", "(C) Over by the copier."], "a": "B", "zh": "我們的網路服務什麼時候會恢復正常？", "ozh": ["不，我不常用。", "中午以前應該修好。", "在影印機旁邊。"]}, {"no": 18, "q": "Have you finished the draft of the report yet?", "o": ["(A) I had a conference call all morning.", "(B) Ms. Yang is a reporter.", "(C) Thanks, I can wait."], "a": "A", "zh": "你完成報告初稿了嗎？", "ozh": ["我整個早上都在開電話會議。", "楊女士是記者。", "謝謝，我可以等。"]}, {"no": 19, "q": "You didn't leave your mobile phone on the train, did you?", "o": ["(A) It's 555-0126.", "(B) A ticket to Amsterdam.", "(C) No, I have it right here."], "a": "C", "zh": "你沒有把手機留在火車上吧？", "ozh": ["號碼是555-0126。", "一張去阿姆斯特丹的車票。", "沒有，就在我這。"]}, {"no": 20, "q": "Could you please replace the tires on my car?", "o": ["(A) He's retiring in May.", "(B) That's a very nice place.", "(C) Yes, we could do it this afternoon."], "a": "C", "zh": "可以請你幫我的汽車更換輪胎嗎？", "ozh": ["他五月退休。", "那是個很好的地方。", "可以，我們今天下午就可以做。"]}, {"no": 21, "q": "What time should we expect the keynote speaker to arrive?", "o": ["(A) She'll be here by nine.", "(B) Yes, I was invited.", "(C) In the lobby."], "a": "A", "zh": "我們預計主講人幾點會到？", "ozh": ["她九點前會到。", "對，我有被邀請。", "在大廳。"]}, {"no": 22, "q": "Did you hear the news about the merger?", "o": ["(A) A small construction firm.", "(B) No, was it announced?", "(C) He's a department head."], "a": "B", "zh": "你聽到合併的消息了嗎？", "ozh": ["一間小型營造公司。", "沒，公佈了嗎？", "他是部門主管。"]}, {"no": 23, "q": "Does our budget include funding for one assistant or two?", "o": ["(A) I didn't know we were hiring anyone.", "(B) At the reception desk.", "(C) It was paid for in cash."], "a": "A", "zh": "我們的預算包含聘請一名還是兩名助理的資金？", "ozh": ["我不知道我們要請人。", "在接待處。", "用現金支付的。"]}, {"no": 24, "q": "That Indian restaurant is big enough for our annual party.", "o": ["(A) They don't have a private dining room.", "(B) A direct flight to India.", "(C) Can I get you some more rice?"], "a": "A", "zh": "那家印度餐廳夠大，適合辦我們的年度派對。", "ozh": ["他們沒有包廂。", "直飛印度的航班。", "需要再給你一些米飯嗎？"]}, {"no": 25, "q": "Is there a computer available to use while mine is being repaired?", "o": ["(A) Isn't it in two hours?", "(B) Michael's not using his today.", "(C) Some updated software."], "a": "B", "zh": "在我的電腦維修期間，有電腦可以使用嗎？", "ozh": ["不是兩小時後嗎？", "麥克今天沒用他的電腦。", "一些更新的軟體。"]}, {"no": 26, "q": "Will you prepare handouts or a slide show for your workshop?", "o": ["(A) Just the new sales director.", "(B) I plan to do both.", "(C) It starts at three o'clock."], "a": "B", "zh": "你會為你的工作坊準備講義還是簡報？", "ozh": ["只有新任銷售總監。", "我打算兩者都做。", "三點開始。"]}, {"no": 27, "q": "The meeting's in Busan, isn't it?", "o": ["(A) It isn't a company I've heard of.", "(B) Yes— I hope we can participate by phone.", "(C) The attendance sheet."], "a": "B", "zh": "會議是在釜山舉行，對吧？", "ozh": ["那不是我聽過的公司。", "是的—希望我們可以電話連線參與。", "簽到表。"]}, {"no": 28, "q": "Can you give me a tour of the property on Thursday?", "o": ["(A) An empty corner lot.", "(B) Leave the door open.", "(C) Let me check my calendar."], "a": "C", "zh": "你週四可以帶我參觀這棟房屋/地產嗎？", "ozh": ["一塊角落空地。", "把門開著。", "讓我看下行事曆。"]}, {"no": 29, "q": "How many days do we have to organize the convention?", "o": ["(A) There are three hundred brochures.", "(B) Don't worry, it's later than last year.", "(C) We'll choose the cheapest one."], "a": "B", "zh": "我們還有多少天可以籌備大會？", "ozh": ["有三百份手冊。", "別擔心，時間比去年晚。", "我們會選最便宜的。"]}, {"no": 30, "q": "I don't think we can afford to start the store renovations yet.", "o": ["(A) That's not what Susan said.", "(B) Yes, it's attracting more customers.", "(C) The product display areas."], "a": "A", "zh": "我認為我們現在還負擔不起開始店面翻修的費用。", "ozh": ["蘇珊可不是這麼說的。", "對，吸引了更多顧客。", "商品展示區。"]}, {"no": 31, "q": "We've met these clients before, haven't we?", "o": ["(A) Sure, I'd be happy to.", "(B) Actually, we shipped them already.", "(C) The manager is new, though."], "a": "C", "zh": "我們以前見過這些客戶，對吧？", "ozh": ["當然，我很樂意。", "實際上我們已經發貨了。", "不過那位經理是新來的。"]}]});
PART2_EXAMS.push({"id": "B-3", "label": "整份音檔 B-3", "kind": "whole", "file": "Part2/New TOEIC B-3.mp3", "starts": [28.01, 46.61, 65.16, 84.3, 103.1, 123.27, 141.82, 161.2, 180.65, 200.73, 220.84, 240.83, 260.57, 280.08, 299.57, 318.51, 337.6, 358.89, 379.9, 400.98, 421.52, 441.44, 462.09, 483.17, 503.31], "ends": [41.52, 60.07, 79.23, 98.04, 118.17, 136.72, 156.1, 175.57, 195.66, 215.75, 235.72, 255.46, 274.95, 294.47, 313.43, 332.42, 353.75, 374.82, 395.9, 416.32, 436.31, 456.98, 478.06, 498.23, 517.53], "questions": [{"no": 7, "q": "Where should I meet you at the theater?", "o": ["(A) In front of the box office.", "(B) It got great reviews.", "(C) The show starts at eight o'clock."], "a": "A", "zh": "我應該在劇院的哪裡跟你會合？", "ozh": ["在售票處前面。", "獲得了很高的評價。", "演出八點開始。"]}, {"no": 8, "q": "The printer on this floor is working, isn't it?", "o": ["(A) No, it's broken.", "(B) Yes, there is.", "(C) Fifty copies."], "a": "A", "zh": "這樓層的影印機是可以用的，對吧？", "ozh": ["不，它壞了。", "有的，那裡有。", "五十份。"]}, {"no": 9, "q": "What should I prepare for the sales workshop?", "o": ["(A) A group of us went.", "(B) Didn't Elizabeth take care of everything?", "(C) That should be fine."], "a": "B", "zh": "我應該為銷售研討會準備什麼？", "ozh": ["我們有一群人去了。", "伊莉莎白不是處理好一切了嗎？", "那應該沒問題。"]}, {"no": 10, "q": "When will the town council election take place?", "o": ["(A) At the town hall.", "(B) At the beginning of June.", "(C) Several candidates."], "a": "B", "zh": "鎮議會選舉什麼時候舉行？", "ozh": ["在鎮公所。", "六月初。", "幾位候選人。"]}, {"no": 11, "q": "Is technical support available twenty-four hours a day?", "o": ["(A) To buy a new watch.", "(B) I don't have questions right now.", "(C) Yes, through our Web site."], "a": "C", "zh": "技術支援是24小時提供的嗎？", "ozh": ["去買一隻新手錶。", "我現在沒有問題。", "是的，透過我們的網站。"]}, {"no": 12, "q": "How much does this sweater cost?", "o": ["(A) It also comes in black.", "(B) Cash only.", "(C) It should say on the tag."], "a": "C", "zh": "這件毛衣多少錢？", "ozh": ["它也有黑色的。", "只收現金。", "標籤上應該有寫。"]}, {"no": 13, "q": "Who gave the presentation on company benefits?", "o": ["(A) Yes, we all went.", "(B) They don't fit.", "(C) Someone in Human Resources."], "a": "C", "zh": "誰做了關於公司福利的簡報？", "ozh": ["是的，我們都去了。", "它們不合身。", "人力資源部的人。"]}, {"no": 14, "q": "Why is there so much traffic?", "o": ["(A) After the weather report.", "(B) Because there's a basketball game today.", "(C) No, that's enough."], "a": "B", "zh": "為什麼車流量這麼大？", "ozh": ["天氣預報之後。", "因為今天有籃球賽。", "不，那樣夠了。"]}, {"no": 15, "q": "Would you be interested in joining the hiring committee?", "o": ["(A) Yes, I'd be honored to.", "(B) Last Wednesday evening.", "(C) It's an interesting article."], "a": "A", "zh": "你有興趣加入招聘委員會嗎？", "ozh": ["是的，我很榮幸。", "上週三晚上。", "這是一篇有趣的報導。"]}, {"no": 16, "q": "Are you going on vacation this month or next month?", "o": ["(A) We're still deciding.", "(B) A different location.", "(C) I'm looking forward to it."], "a": "A", "zh": "你這個月還是下個月要休假？", "ozh": ["我們還在決定。", "不同的地點。", "我很期待。"]}, {"no": 17, "q": "How do I get a new identification card?", "o": ["(A) There's an online form to fill out.", "(B) To carry in your wallet.", "(C) By February 21."], "a": "A", "zh": "我該如何取得新的識別證？", "ozh": ["有線上表格需要填寫。", "放進你的皮夾裡。", "二月二十一日前。"]}, {"no": 18, "q": "Shall I send out the agenda for the meeting?", "o": ["(A) Not in general.", "(B) Uh, I have to make a revision first.", "(C) Conference room C is large enough."], "a": "B", "zh": "我要發送會議議程了嗎？", "ozh": ["一般來說不是。", "額，我得先修改一下。", "C會議室夠大。"]}, {"no": 19, "q": "Who was selected to work on the advertising project?", "o": ["(A) A great success.", "(B) It's a popular brand.", "(C) I haven't heard."], "a": "C", "zh": "誰被選中參與廣告專案？", "ozh": ["巨大的成功。", "這是個熱門品牌。", "我還沒聽說。"]}, {"no": 20, "q": "The ferry to the island runs every half hour, doesn't it?", "o": ["(A) Yes, there's one coming now.", "(B) No thanks, that's too late.", "(C) At the ticket kiosk."], "a": "A", "zh": "前往離島的渡輪每半小時一班，對吧？", "ozh": ["對，現在就有一班過來。", "不用了謝謝，太晚了。", "在售票亭。"]}, {"no": 21, "q": "How should I pay the deposit on the rental car?", "o": ["(A) Do you have a credit card?", "(B) It's less expensive than that.", "(C) Yes, there's plenty of space."], "a": "A", "zh": "我該如何支付租車押金？", "ozh": ["你有信用卡嗎？", "比那個便宜。", "有，空間很大。"]}, {"no": 22, "q": "Who's responsible for the packaging design?", "o": ["(A) It was shipped overnight.", "(B) Just sign here.", "(C) Martin's team."], "a": "C", "zh": "誰負責包裝設計？", "ozh": ["已隔夜運送。", "在這裡簽名即可。", "馬丁的團隊。"]}, {"no": 23, "q": "Is Mr. Kim in charge of the manufacturing plant?", "o": ["(A) Weren't some planted recently?", "(B) I think someone else is managing it now.", "(C) Just small production defect."], "a": "B", "zh": "金先生負責製造工廠嗎？", "ozh": ["最近不是才種了一些嗎？", "我想現在是別人在管理。", "只是小的生產瑕疵。"]}, {"no": 24, "q": "Why don't we offer a vegetarian dish at the lunch?", "o": ["(A) I've been there a few times.", "(B) It may be too late to change the menu.", "(C) No, let's wash the dishes later."], "a": "B", "zh": "我們午餐為何不提供素食菜餚呢？", "ozh": ["我去過那裡幾次。", "現在更改菜單可能太晚了。", "不，我們待會再洗碗。"]}, {"no": 25, "q": "Where does John usually store the extra supplies?", "o": ["(A) There's one on the corner of Main Street.", "(B) Sure, that might be a good idea.", "(C) You'd better ask him."], "a": "C", "zh": "約翰通常把多餘的用品放在哪裡？", "ozh": ["主街轉角有一家。", "當然，那可能是個好主意。", "你最好問他。"]}, {"no": 26, "q": "I found a new supplier for the garden fertilizer we use.", "o": ["(A) Do they have good prices?", "(B) In the warehouse.", "(C) We sold a lot of flowers."], "a": "A", "zh": "我找到了一家我們使用的花園肥料的新供應商。", "ozh": ["他們價格好嗎？", "在倉庫裡。", "我們賣了很多花。"]}, {"no": 27, "q": "How about holding a training seminar on the new database?", "o": ["(A) Yes, I think we should.", "(B) I've been there before.", "(C) It went very well."], "a": "A", "zh": "舉辦一場新資料庫的培訓研討會怎麼樣？", "ozh": ["好啊，我覺得應該辦。", "我以前去過那裡。", "進行得很順利。"]}, {"no": 28, "q": "Didn't you organize the employee picnic last year?", "o": ["(A) You can use the Milton Room.", "(B) I've done it the past seven years.", "(C) No, it was free."], "a": "B", "zh": "你去年不是籌辦了員工野餐嗎？", "ozh": ["你可以使用彌爾頓廳。", "過去七年都是我辦的。", "不，那是免費的。"]}, {"no": 29, "q": "Would you take this memo to the Finance Department?", "o": ["(A) Sure, I'll drop it off before the meeting.", "(B) I had to pay a small fine.", "(C) Right on the first page."], "a": "A", "zh": "你可以把這份備忘錄送到財務部嗎？", "ozh": ["沒問題，我會在開會前送去。", "我必須支付一筆小額罰款。", "就在第一頁。"]}, {"no": 30, "q": "Shall I contact you by e-mail or by phone?", "o": ["(A) OK, I'll take a look at the contract.", "(B) Oh, did you?", "(C) Actually, I'll be seeing you tomorrow."], "a": "C", "zh": "我該用電子郵件還是電話聯絡你？", "ozh": ["好的，我會看下合約。", "噢，是嗎？", "實際上我明天就會見到你了。"]}, {"no": 31, "q": "Are you still working on the final budget?", "o": ["(A) The decision was final.", "(B) I usually start work at nine.", "(C) I'm not, but Janet is."], "a": "C", "zh": "你還在處理最終預算案嗎？", "ozh": ["決定是最終的。", "我通常九點開始工作。", "我沒有，但珍妮特在做。"]}]});
PART2_EXAMS.push({"id": "B-9", "label": "整份音檔 B-9", "kind": "whole", "file": "Part2/New TOEIC B-9.mp3", "starts": [28.3, 47.3, 65.68, 85.3, 105.62, 125.94, 147.61, 166.51, 186.28, 208.0, 228.73, 250.83, 271.84, 292.57, 313.96, 333.5, 355.41, 377.21, 397.19, 416.67, 438.36, 460.06, 479.49, 501.5, 521.28], "ends": [41.84, 60.3, 79.9, 100.31, 120.62, 142.16, 161.04, 180.81, 202.61, 223.33, 245.4, 266.34, 287.15, 308.61, 328.08, 349.97, 371.75, 391.72, 411.24, 432.93, 454.66, 474.02, 496.08, 515.79, 535.59], "questions": [{"no": 7, "q": "When does the shuttle bus leave for the airport?", "o": ["(A) Every hour on the hour.", "(B) In the hotel lobby.", "(C) Twelve dollars."], "a": "A", "zh": "前往機場的接駁車什麼時候發車？", "ozh": ["每整點一班。", "在飯店大廳。", "十二美元。"]}, {"no": 8, "q": "Where can I find the printer?", "o": ["(A) Thirty pages at a time.", "(B) Monday to Friday.", "(C) Down the hall to your left."], "a": "C", "zh": "我在哪裡可以找到印表機？", "ozh": ["一次三十頁。", "週一至週五。", "順著走廊走，在你的左手邊。"]}, {"no": 9, "q": "Who will be going to the exposition this year?", "o": ["(A) It was a good experience.", "(B) Several of our colleagues.", "(C) The beginning of October."], "a": "B", "zh": "今年誰要去博覽會？", "ozh": ["那是個很好的經驗。", "我們幾位同事。", "十月初。"]}, {"no": 10, "q": "Would you like me to bring you another soft drink?", "o": ["(A) That's OK, I don't want one.", "(B) No, that's the first time I've heard it.", "(C) The dinner reservation's at eight."], "a": "A", "zh": "需要我幫你拿另一杯汽水/軟性飲料嗎？", "ozh": ["不用了，我不需要。", "不，那是我第一次聽到。", "晚餐預訂在八點。"]}, {"no": 11, "q": "Is Maria going to present the sales report, or are you doing it?", "o": ["(A) We're doing it together.", "(B) It's on sale today.", "(C) In a couple of weeks."], "a": "A", "zh": "瑪利亞要做銷售報告簡報，還是你做？", "ozh": ["我們要一起做。", "今天特價。", "幾週後。"]}, {"no": 12, "q": "What's the name of the new intern in the design department?", "o": ["(A) I think it's Sammy, but I'm not sure.", "(B) We sent in the blueprint.", "(C) Yes, I enjoyed the internship."], "a": "A", "zh": "設計部新實習生叫什麼名字？", "ozh": ["我想是薩米，但不確定。", "我們寄出了藍圖。", "是的，我很享受實習。"]}, {"no": 13, "q": "Are you ready for your next patient?", "o": ["(A) Usually thirty minutes.", "(B) I already read it.", "(C) Sure, send her in."], "a": "C", "zh": "你準備好接見下一位病人了嗎？", "ozh": ["通常三十小時/分鐘。", "我已經看過了。", "當然，讓她進來。"]}, {"no": 14, "q": "How do you turn the packaging machine on?", "o": ["(A) Next to the storage area.", "(B) Push the green button.", "(C) No, I haven't seen her."], "a": "B", "zh": "你怎麼開動這台包裝機？", "ozh": ["在儲藏區旁邊。", "按綠色按鈕。", "不，我沒看到她。"]}, {"no": 15, "q": "You went to the soccer match last week, didn't you?", "o": ["(A) These socks don't match.", "(B) A local sports writer.", "(C) I did—my favorite team won!"], "a": "C", "zh": "你上週去看足球比賽了，對吧？", "ozh": ["這雙襪子不配對。", "當地的體育作家。", "有啊—我最喜歡的球隊贏了！"]}, {"no": 16, "q": "Will you stay after the show to meet the musicians?", "o": ["(A) I think so too.", "(B) Almost as long as the previous show.", "(C) Don't they leave as soon as it's over?"], "a": "C", "zh": "表演結束後你會留下來見音樂家嗎？", "ozh": ["我也這麼認為。", "幾乎跟前一場表演一樣長。", "他們不是一結束就離開嗎？"]}, {"no": 17, "q": "How often do you buy new glasses?", "o": ["(A) About three to five days per order.", "(B) The store on Robin Street.", "(C) I actually switched to contact lenses."], "a": "C", "zh": "你多久買一次新眼鏡？", "ozh": ["每個訂單約三到五天。", "羅賓街上的那家店。", "實際上我改成戴隱形眼鏡了。"]}, {"no": 18, "q": "Didn't the clients say they'd prefer to tour the factory today?", "o": ["(A) A job application.", "(B) Their schedule is already full.", "(C) It's a new building."], "a": "B", "zh": "客戶不是說他們今天比較想參觀工廠嗎？", "ozh": ["求職申請。", "他們的行程已經排滿了。", "這是一棟新大樓。"]}, {"no": 19, "q": "I can pick up your packages while I'm at the post office.", "o": ["(A) Thanks, but I already got them.", "(B) I picked the cheapest one.", "(C) Did you send it through the mail?"], "a": "A", "zh": "我去郵局時可以順便幫你拿包裹。", "ozh": ["謝謝，但我已經拿到了。", "我挑了最便宜的。", "你是用郵寄的嗎？"]}, {"no": 20, "q": "Which page should I turn to in the manual?", "o": ["(A) Make a left just past that stop sign.", "(B) Wait, that's the wrong manual.", "(C) Maybe several hours ago."], "a": "B", "zh": "我應該翻到手冊的哪一頁？", "ozh": ["過了那個停車標誌後左轉。", "等等，那本手冊拿錯了。", "大概幾個小時前。"]}, {"no": 21, "q": "Where are your photographs being exhibited now?", "o": ["(A) Only in black and white.", "(B) At the community center.", "(C) Almost a month."], "a": "B", "zh": "你的照片現在在哪裡展出？", "ozh": ["只有黑白的。", "在社區中心。", "快一個月。"]}, {"no": 22, "q": "This database could be more user-friendly.", "o": ["(A) More than five hundred surveys.", "(B) We're working on updates right now.", "(C) Choose a new user name and password."], "a": "B", "zh": "這個資料庫可以做得更人性化/易用一些。", "ozh": ["超過五百份調查。", "我們現在正在進行更新。", "選擇新的用戶名和密碼。"]}, {"no": 23, "q": "When did your company start importing steel?", "o": ["(A) A nineteen percent increase.", "(B) Central and South America, mostly.", "(C) I'd have to check our records."], "a": "C", "zh": "貴公司是什麼時候開始進口鋼鐵的？", "ozh": ["百分之十九的增長。", "主要在中南美洲。", "我必須查一下我們的紀錄。"]}, {"no": 24, "q": "We found some defects in the accounting software.", "o": ["(A) That's unfortunate.", "(B) He's on the third floor.", "(C) The bank canceled it."], "a": "A", "zh": "我們在會計軟體中發現了一些瑕疵/漏洞。", "ozh": ["那太令人遺憾了。", "他在三樓。", "銀行取消了。"]}, {"no": 25, "q": "Why didn't you take the bus today?", "o": ["(A) Outside my apartment.", "(B) Because Wendy drove me.", "(C) A three-day workshop."], "a": "B", "zh": "你今天為什麼沒搭公車？", "ozh": ["在我公寓外面。", "因為溫蒂載我。", "為期三天的工作坊。"]}, {"no": 26, "q": "We can have the replacement parts by Friday, right?", "o": ["(A) Put it on the lowest shelf.", "(B) Yes—but shipping costs more.", "(C) No, at the next traffic light."], "a": "B", "zh": "我們在週五前能收到替換零件，對吧？", "ozh": ["把它放在最底層架子上。", "對—但運費比較貴。", "不，在下個紅綠燈。"]}, {"no": 27, "q": "The CEO's presentation is in Conference Room C.", "o": ["(A) This book makes a great present.", "(B) Oh — I was headed the wrong way.", "(C) On the last page."], "a": "B", "zh": "執行長的簡報在C會議室。", "ozh": ["這本書當禮物很棒。", "噢—我剛走錯方向了。", "在最後一頁。"]}, {"no": 28, "q": "Isn't the gym open twenty-four hours?", "o": ["(A) Only on the weekend.", "(B) Yes, she's really helpful.", "(C) That's when it's due."], "a": "A", "zh": "健身房不是24小時營業嗎？", "ozh": ["只有週末是。", "對，她真的很熱心。", "那是到期的時候。"]}, {"no": 29, "q": "Why are we starting with training module four?", "o": ["(A) At the top of page 112.", "(B) I'd prefer a later time if possible.", "(C) This is the advanced session."], "a": "C", "zh": "我們為什麼要從訓練模組四開始？", "ozh": ["在112頁頂端。", "如果可以的話，我比較希望晚一點。", "這是進階場次。"]}, {"no": 30, "q": "Who's organizing this month's book club meeting?", "o": ["(A) At the library, of course.", "(B) I did it last time.", "(C) It's a best seller."], "a": "B", "zh": "這個月的讀書會是誰籌辦的？", "ozh": ["當然是在圖書館。", "上次是我辦的。", "這是暢銷書。"]}, {"no": 31, "q": "Let's look at some rental properties today.", "o": ["(A) I'll have more time tomorrow.", "(B) Oh, congratulations!", "(C) I think it was Carla."], "a": "A", "zh": "我們今天去看一些出租房屋吧。", "ozh": ["我明天時間比較充裕。", "噢，恭喜！", "我想是卡拉。"]}]});
